-- Catalogue de la base : descriptions en français des 184 tables/vues et de leurs colonnes
-- (25/11/2026). Préparation du connecteur « Data Al Baraka » en lecture seule pour l'équipe :
-- Claude lit ces commentaires pour comprendre les tables et écrire des requêtes justes.
-- Uniquement des COMMENT ON : aucune donnée, aucun droit, aucun comportement de l'appli ne change.
-- Les colonnes notées « (masquée pour le connecteur) » contiennent des clés qui permettent d'agir
-- (jetons, secrets) : elles ne seront pas lisibles par le connecteur.
-- Appliqué en base le 25/11/2026.

COMMENT ON TABLE public.ab_conversions IS 'Une conversion d''un visiteur exposé à un test A/B : au plus une par test, visiteur et action. L''inscription est écrite par tunnel-lead-submit ; groupe WhatsApp et RDV par ab-convert. La variante vient de l''exposition. Taux = conversions / expositions du même test.';
COMMENT ON COLUMN public.ab_conversions."test_id" IS 'Test concerné (ab_tests.id).';
COMMENT ON COLUMN public.ab_conversions."visitor_id" IS 'Identifiant anonyme du navigateur, même valeur que dans ab_exposures.';
COMMENT ON COLUMN public.ab_conversions."variant" IS 'Variante vue (recopiée depuis ab_exposures).';
COMMENT ON COLUMN public.ab_conversions."action" IS 'inscription = lead créé (test de landing) ; groupe_whatsapp = clic vers le groupe ; rendez_vous = prise de RDV (tests de page merci).';
COMMENT ON TABLE public.ab_exposures IS 'Un visiteur exposé à une variante d''un test A/B (une seule ligne par test et par visiteur) : c''est le dénominateur du taux de conversion. Écrit par l''edge function ab-visit. Relier aux conversions par (test_id, visitor_id) et aux leads par leads.visitor_id.';
COMMENT ON COLUMN public.ab_exposures."test_id" IS 'Test concerné (ab_tests.id).';
COMMENT ON COLUMN public.ab_exposures."visitor_id" IS 'Identifiant anonyme du navigateur (cookie), même valeur que leads.visitor_id.';
COMMENT ON COLUMN public.ab_exposures."variant" IS 'Variante réellement servie à ce visiteur.';
COMMENT ON COLUMN public.ab_exposures."tunnel" IS 'Tunnel de la visite (wa ou vsl).';
COMMENT ON COLUMN public.ab_exposures."src" IS 'Jeton de trafic de la visite (?src=), ex. ads, ig, tiktok, youtube, direct.';
COMMENT ON TABLE public.ab_tests IS 'Un test A/B sur un tunnel (une ligne par test). Créé depuis la page A/B tests (CEO) ; le code voyage dans l''URL (?ab=CODE). Expositions dans ab_exposures, conversions dans ab_conversions. Pour changer de variantes on crée un nouveau test. Peu ou pas de données à ce jour (à vérifier).';
COMMENT ON COLUMN public.ab_tests."code" IS 'Code court du test (4 à 8 caractères, sans I/O/0/1), présent dans l''URL ?ab= et recopié dans leads.ab_test_code.';
COMMENT ON COLUMN public.ab_tests."libelle" IS 'Nom lisible du test.';
COMMENT ON COLUMN public.ab_tests."tunnel" IS 'Tunnel testé : wa = tunnel WhatsApp (conférence) ; vsl = tunnel VSL.';
COMMENT ON COLUMN public.ab_tests."canal" IS 'Jeton de trafic visé (?src=) : ads, ig, tiktok, youtube. NULL = tout le trafic.';
COMMENT ON COLUMN public.ab_tests."variants" IS 'Liste des variantes servies (2 à 6), ex. numéros de vidéo ?v=.';
COMMENT ON COLUMN public.ab_tests."weights" IS 'Poids de tirage de chaque variante, dans le même ordre que variants.';
COMMENT ON COLUMN public.ab_tests."metrique" IS 'Indicatif seulement (lead ou vente). L''action décisive est dans action.';
COMMENT ON COLUMN public.ab_tests."statut" IS 'running = en cours ; stopped = arrêté (voir arrete_le, conclusion).';
COMMENT ON COLUMN public.ab_tests."demarre_le" IS 'Début du test.';
COMMENT ON COLUMN public.ab_tests."arrete_le" IS 'Fin du test ; NULL tant qu''il tourne.';
COMMENT ON COLUMN public.ab_tests."conclusion" IS 'Conclusion écrite à l''arrêt du test.';
COMMENT ON COLUMN public.ab_tests."cree_par" IS 'Auteur du test (profiles.id).';
COMMENT ON COLUMN public.ab_tests."action" IS 'Conversion mesurée : inscription (test de landing) ; groupe_whatsapp ou rendez_vous (test de page merci).';
COMMENT ON COLUMN public.ab_tests."etape" IS 'Où la variante est vue : landing (conversion = inscription) ou merci (conversion = groupe WhatsApp ou RDV).';
COMMENT ON TABLE public.acces_manuels IS 'Dérogations manuelles du CEO aux règles d''accès automatiques (coachings, formations, fonctionnalités, pass) : autoriser ou bloquer, motif obligatoire. Une dérogation active (revoque_le NULL, non expirée) l''emporte sur l''automatique ; résolution par la fonction acces_de. Une seule dérogation active par (user_id, domaine, cible).';
COMMENT ON COLUMN public.acces_manuels."user_id" IS 'Personne concernée (profiles.id).';
COMMENT ON COLUMN public.acces_manuels."domaine" IS 'coaching, formation, fonctionnalite ou pass.';
COMMENT ON COLUMN public.acces_manuels."cible" IS 'Ce qui est ouvert/bloqué dans le domaine (formation, créneau de coaching, fonctionnalité, pass) ; format exact défini par acces_de.';
COMMENT ON COLUMN public.acces_manuels."decision" IS 'autorise = ouvert malgré les règles ; bloque = fermé malgré les règles.';
COMMENT ON COLUMN public.acces_manuels."motif" IS 'Raison de la dérogation (3 caractères minimum).';
COMMENT ON COLUMN public.acces_manuels."expire_le" IS 'Fin automatique de la dérogation ; NULL = sans limite.';
COMMENT ON COLUMN public.acces_manuels."accorde_par" IS 'CEO qui a posé la dérogation.';
COMMENT ON COLUMN public.acces_manuels."accorde_le" IS 'Date de la dérogation.';
COMMENT ON COLUMN public.acces_manuels."revoque_le" IS 'Retour au régime automatique ; NULL = dérogation active.';
COMMENT ON COLUMN public.acces_manuels."revoque_par" IS 'Auteur du retrait.';
COMMENT ON TABLE public.access_audit_log IS 'Journal des actions admin sur les accès d''un utilisateur (invitations, changement d''e-mail, accès anticipé, pass, inscriptions). Alimente l''historique de la page admin des accès. Les pass et inscriptions sont aussi tracés dans leurs propres tables.';
COMMENT ON COLUMN public.access_audit_log."user_id" IS 'Utilisateur concerné (profiles.id).';
COMMENT ON COLUMN public.access_audit_log."action" IS 'invitation_sent, email_changed, early_access_granted/revoked, pass_granted/revoked, enrollment_granted/revoked.';
COMMENT ON COLUMN public.access_audit_log."details" IS 'Détails JSON de l''action (ancienne/nouvelle valeur…).';
COMMENT ON COLUMN public.access_audit_log."performed_by" IS 'Auteur de l''action (profiles.id) ; NULL possible.';
COMMENT ON TABLE public.activation_journal IS 'Journal des essais d''activation de l''accès élève (page d''activation / mot de passe), mis en place après la panne du 20/10/2026. Une ligne par étape tentée. Écrit par la fonction activation_noter, appelable sans être connecté (au plus 300 lignes par heure). Lecture CEO.';
COMMENT ON COLUMN public.activation_journal."cree_le" IS 'Date et heure de l''essai.';
COMMENT ON COLUMN public.activation_journal."utilisateur" IS 'Utilisateur concerné (profiles.id), NULL si inconnu à cette étape.';
COMMENT ON COLUMN public.activation_journal."etape" IS 'lien_ouvert = lien d''activation ouvert ; mot_de_passe = enregistrement du mot de passe.';
COMMENT ON COLUMN public.activation_journal."succes" IS 'true = étape réussie.';
COMMENT ON COLUMN public.activation_journal."detail" IS 'Message d''erreur ou détail (300 caractères max).';
COMMENT ON COLUMN public.activation_journal."duree_ms" IS 'Durée de l''étape en millisecondes.';
COMMENT ON COLUMN public.activation_journal."navigateur" IS 'Navigateur abrégé (60 caractères max).';
COMMENT ON TABLE public.activity_daily_kpis IS 'Une ligne = la saisie d''une journée d''un élève dans « Mon Activité » (/working/activity, débloquée après la partie Setting). Chiffres DÉCLARÉS par l''élève, sans lien avec les tables calls/sales. Unique (user_id, entry_date). Le retour IA du jour est écrit par l''edge function activity-ai-coach-daily. Sert aussi au classement entre élèves.';
COMMENT ON COLUMN public.activity_daily_kpis."user_id" IS 'Élève (profiles.id).';
COMMENT ON COLUMN public.activity_daily_kpis."entry_date" IS 'Jour saisi (date locale de l''élève, pas d''heure).';
COMMENT ON COLUMN public.activity_daily_kpis."videos_published" IS 'Vidéos publiées ce jour-là (déclaratif).';
COMMENT ON COLUMN public.activity_daily_kpis."messages_sent" IS 'Messages de prospection envoyés (déclaratif).';
COMMENT ON COLUMN public.activity_daily_kpis."replies_received" IS 'Réponses reçues aux messages (déclaratif).';
COMMENT ON COLUMN public.activity_daily_kpis."appointments" IS 'RDV obtenus (déclaratif). Présents = appointments − no_shows.';
COMMENT ON COLUMN public.activity_daily_kpis."sales_made" IS 'Ventes déclarées par l''élève. Ce ne sont PAS les ventes de la table sales.';
COMMENT ON COLUMN public.activity_daily_kpis."no_shows" IS 'RDV non honorés parmi appointments (ajouté le 13/10/2026 ; 0 pour les journées saisies avant).';
COMMENT ON COLUMN public.activity_daily_kpis."ai_feedback" IS 'Conseil IA généré après la saisie (edge function activity-ai-coach-daily). Null = pas encore généré.';
COMMENT ON TABLE public.activity_objectives IS 'Objectifs GLOBAUX de « Mon Activité », identiques pour tous les élèves : une ligne par indicateur. Réglés par le CEO. Pas d''objectif individuel.';
COMMENT ON COLUMN public.activity_objectives."kpi_key" IS 'Indicateur : videos, messages, replies, appointments, sales (correspond aux colonnes de activity_daily_kpis).';
COMMENT ON COLUMN public.activity_objectives."weekly_target" IS 'Objectif par semaine.';
COMMENT ON COLUMN public.activity_objectives."daily_target" IS 'Objectif par jour.';
COMMENT ON TABLE public.activity_weekly_recaps IS 'Une ligne = le récap IA de la semaine écoulée d''un élève, généré chaque lundi par l''edge function activity-weekly-recap à partir de activity_daily_kpis. Unique (user_id, week_start).';
COMMENT ON COLUMN public.activity_weekly_recaps."user_id" IS 'Élève (profiles.id).';
COMMENT ON COLUMN public.activity_weekly_recaps."week_start" IS 'Lundi de la semaine résumée.';
COMMENT ON COLUMN public.activity_weekly_recaps."recap_text" IS 'Texte du récap généré par l''IA.';
COMMENT ON COLUMN public.activity_weekly_recaps."stats" IS 'JSON : days_filled, days_missed, totals (semaine), prev_totals et prev2_totals (2 semaines précédentes).';
COMMENT ON COLUMN public.activity_weekly_recaps."dismissed_at" IS 'Moment où l''élève a fermé le récap. Null = pas encore fermé.';
COMMENT ON VIEW public.activity_weekly_totals IS 'Vue : somme par élève et par semaine (lundi) de activity_daily_kpis. Recalculée à chaque lecture. Chiffres déclaratifs.';
COMMENT ON COLUMN public.activity_weekly_totals."week_start" IS 'Lundi de la semaine (date_trunc(''week'')).';
COMMENT ON COLUMN public.activity_weekly_totals."days_filled" IS 'Nombre de jours saisis dans la semaine (0 à 7).';
COMMENT ON COLUMN public.activity_weekly_totals."sales_made" IS 'Ventes déclarées par l''élève, pas les ventes réelles (table sales).';
COMMENT ON TABLE public.ads IS 'Dépense pub par CAMPAGNE et par jour (Meta, Snap, Google). Remontée chaque matin par Make via l''edge function depenses-pub (7 derniers jours relus et remplacés). Référence des totaux de dépense du tableau de bord. Dépense du jour connue le lendemain. Seules les lignes à dépense > 0 sont gardées. Unicité (plateforme, date, campaign_id). Lignes antérieures au 31/10/2026 : anciens scénarios Make, compte_id et importe_le vides.';
COMMENT ON COLUMN public.ads."date" IS 'Jour de la dépense, dans le fuseau du compte publicitaire (Meta : Paris ; Snap : UTC+4).';
COMMENT ON COLUMN public.ads."campaign_name" IS 'Nom de la campagne, mis en MAJUSCULES à l''import.';
COMMENT ON COLUMN public.ads."campaign_id" IS 'Identifiant de la campagne dans la plateforme. Unique seulement à l''intérieur d''une plateforme. Correspond à leads.utm_campaign pour Meta/Snap.';
COMMENT ON COLUMN public.ads."channel" IS 'Ancien tunnel saisi (VENTE DIRECTE, VSL, WEBINAIRE, WHATSAPP). Les imports depuis le 31/10/2026 écrivent toujours WEBINAIRE : ne pas s''en servir pour ventiler par tunnel.';
COMMENT ON COLUMN public.ads."amount_spent" IS 'Dépense du jour en euros (devise), arrondie au centime. Montant tel que facturé par la plateforme (pas de notion HT/TTC dans l''import).';
COMMENT ON COLUMN public.ads."impressions" IS 'Impressions du jour pour la campagne.';
COMMENT ON COLUMN public.ads."clicks" IS 'Clics du jour pour la campagne (définition propre à chaque plateforme).';
COMMENT ON COLUMN public.ads."plateforme" IS 'meta, snap ou google. Lignes anciennes : meta par défaut.';
COMMENT ON COLUMN public.ads."compte_id" IS 'Compte publicitaire d''origine (cf. ads_comptes). Vide sur les lignes antérieures au 31/10/2026.';
COMMENT ON COLUMN public.ads."devise" IS 'Devise de amount_spent ; EUR en pratique.';
COMMENT ON COLUMN public.ads."importe_le" IS 'Dernière réception de la ligne par Make. Vide sur les lignes anciennes.';
COMMENT ON TABLE public.ads_comptes IS 'Liste des comptes publicitaires suivis (un par plateforme et identifiant). Sert à surveiller les remontées Make (retard si aucun import depuis 36 h) et à calculer « dépenses connues jusqu''au ». Lecture CEO. Clé primaire (plateforme, compte_id).';
COMMENT ON COLUMN public.ads_comptes."compte_id" IS 'Identifiant du compte dans la plateforme (ex. act_… pour Meta). Jointure avec ads.compte_id, ads_pubs.compte_id, ads_imports.compte_id.';
COMMENT ON COLUMN public.ads_comptes."nom" IS 'Libellé lisible du compte.';
COMMENT ON COLUMN public.ads_comptes."actif" IS 'true = compte surveillé et attendu chaque matin ; false = plus suivi.';
COMMENT ON TABLE public.ads_imports IS 'Journal de chaque envoi de Make reçu par depenses-pub : une ligne par réception et par compte. Sert à dater la dernière remontée et à détecter un compte en retard. Ne contient pas de dépense : la dépense est dans ads (niveau campagne) et ads_pubs (niveau pub).';
COMMENT ON COLUMN public.ads_imports."recu_le" IS 'Date et heure de réception de l''envoi (timestamptz).';
COMMENT ON COLUMN public.ads_imports."lignes" IS 'Nombre de lignes insérées ou mises à jour lors de cet envoi.';
COMMENT ON COLUMN public.ads_imports."effacees" IS 'Nombre de lignes effacées : jours/campagnes que la plateforme ne renvoie plus sur la période reçue (dépense annulée).';
COMMENT ON COLUMN public.ads_imports."erreur" IS 'Message d''erreur de l''import ; NULL = import réussi.';
COMMENT ON COLUMN public.ads_imports."niveau" IS 'campagne = remontée vers ads ; pub = remontée par pub vers ads_pubs (depuis le 03/11/2026).';
COMMENT ON TABLE public.ads_pubs IS 'Dépense par PUB (créa) et par jour, Meta et Snap seulement (Google ne donne pas d''id de pub). Remontée par un second scénario Make depuis le 03/11/2026 (données antérieures importées ponctuellement). Sert à l''onglet « Par créa ». Les totaux officiels restent sur ads : ne pas additionner ads et ads_pubs. Seules les lignes à dépense > 0. Clé (plateforme, date, pub_id).';
COMMENT ON COLUMN public.ads_pubs."date" IS 'Jour de la dépense, dans le fuseau du compte (Meta : Paris ; Snap : UTC+4).';
COMMENT ON COLUMN public.ads_pubs."pub_id" IS 'Identifiant de la pub. Correspond à leads.utm_content pour les leads Meta/Snap.';
COMMENT ON COLUMN public.ads_pubs."pub_nom" IS 'Nom de la pub (créa) au moment de l''import.';
COMMENT ON COLUMN public.ads_pubs."groupe_id" IS 'Identifiant du groupe d''annonces (ad set / ad squad).';
COMMENT ON COLUMN public.ads_pubs."groupe_nom" IS 'Nom du groupe d''annonces.';
COMMENT ON COLUMN public.ads_pubs."campagne_id" IS 'Identifiant de la campagne parente (même valeur que ads.campaign_id).';
COMMENT ON COLUMN public.ads_pubs."campagne_nom" IS 'Nom de la campagne parente (casse d''origine, contrairement à ads).';
COMMENT ON COLUMN public.ads_pubs."depense" IS 'Dépense du jour pour la pub, en euros (devise).';
COMMENT ON COLUMN public.ads_pubs."clics" IS 'Clics du jour pour la pub.';
COMMENT ON COLUMN public.ads_pubs."importe_le" IS 'Dernière réception de la ligne par Make.';
COMMENT ON TABLE public.agent_conversations IS 'Une conversation avec l''Agent IA Setting (page /working/agent, débloquée après la partie SETTING du parcours Setting/Closing). Créée par la page au 1er message ; les messages sont dans agent_messages. Supprimable par l''utilisateur (suppression physique). Le coût IA n''est pas ici : ia_consommations, fonctionnalite = ''agent_setting'' (sans lien vers la conversation).';
COMMENT ON COLUMN public.agent_conversations."user_id" IS 'Utilisateur (setter, apporteur, élève) propriétaire de la conversation ; = profiles.id.';
COMMENT ON COLUMN public.agent_conversations."title" IS 'Titre : les 50 premiers caractères du 1er message de l''utilisateur, renommable par lui.';
COMMENT ON COLUMN public.agent_conversations."updated_at" IS 'Dernière activité (sert au tri de l''historique).';
COMMENT ON TABLE public.agent_knowledge_base IS 'Base de connaissance de l''Agent IA Setting : une ligne = une fiche (script ou objection) injectée telle quelle dans les instructions de l''IA par l''edge function claude-agent-prospect (cache 60 s). Modifiée par le CEO dans /admin/agent-knowledge (titre et contenu seulement). Contenu métier, pas de données d''activité.';
COMMENT ON COLUMN public.agent_knowledge_base."slug" IS 'Identifiant technique stable de la fiche.';
COMMENT ON COLUMN public.agent_knowledge_base."category" IS 'scripts = script de messages ; objections = réponse type à une objection ; system = consigne générale (autorisé, aucune ligne à ce jour).';
COMMENT ON COLUMN public.agent_knowledge_base."content" IS 'Texte de la fiche, transmis mot pour mot à l''IA.';
COMMENT ON COLUMN public.agent_knowledge_base."sort_order" IS 'Ordre d''injection dans les instructions de l''IA et d''affichage.';
COMMENT ON COLUMN public.agent_knowledge_base."updated_by" IS 'Dernier membre (CEO) ayant modifié la fiche ; = profiles.id.';
COMMENT ON TABLE public.agent_messages IS 'Un message d''une conversation avec l''Agent IA Setting (agent_conversations). La page enregistre le message de l''utilisateur puis la réponse de l''IA. Pour mesurer l''usage, compter les messages role = ''user'' (une question = un appel IA).';
COMMENT ON COLUMN public.agent_messages."conversation_id" IS 'Conversation ; = agent_conversations.id.';
COMMENT ON COLUMN public.agent_messages."role" IS 'user = message tapé par l''utilisateur (souvent un DM de prospect collé) ; assistant = réponse de l''IA (3 blocs : psychologie, réponse à copier, pourquoi).';
COMMENT ON COLUMN public.agent_messages."content" IS 'Texte du message.';
COMMENT ON TABLE public.announcements IS 'Annonces publiées par le CEO aux membres de la plateforme. À la publication, un trigger crée une notification de type announcement pour chaque utilisateur des rôles ciblés ; supprimer l''annonce supprime ces notifications.';
COMMENT ON COLUMN public.announcements."author_id" IS 'Auteur (profiles.id, le CEO).';
COMMENT ON COLUMN public.announcements."title" IS 'Titre de l''annonce.';
COMMENT ON COLUMN public.announcements."body" IS 'Texte de l''annonce.';
COMMENT ON COLUMN public.announcements."target_roles" IS 'Rôles destinataires (valeurs de profiles.role).';
COMMENT ON COLUMN public.announcements."published_at" IS 'Date de publication ; NULL = brouillon non visible.';
COMMENT ON TABLE public.app_settings IS 'Réglages applicatifs clé → valeur JSON (ex. training_coming_soon_enabled). ATTENTION : contient aussi des identifiants d''API (Twilio, systeme.io, secret de facturation interne) lus par les edge functions ; la colonne value ne doit pas être exposée pour ces clés.';
COMMENT ON COLUMN public.app_settings."key" IS 'Nom du réglage (clé primaire).';
COMMENT ON COLUMN public.app_settings."value" IS 'Valeur JSON du réglage. Pour les clés d''API (twilio_*, systeme_io_api_key, internal_invoice_secret), c''est un secret (masquée pour le connecteur).';
COMMENT ON COLUMN public.app_settings."updated_by" IS 'Dernier auteur de la modification (users.id).';
COMMENT ON TABLE public.appels_analyses IS 'Une analyse d''appel d''élève (V1 coach, depuis le 25/10/2026) : un coach ou le CEO dépose l''enregistrement, une machine transcrit, sépare les voix, mesure et note avec le référentiel actif, puis le coach valide ou corrige (/coaching/analyse-appels). Seul le Setting ADS existe. L''élève ne voit rien dans la plateforme. Audio effacé après 30 jours (cron appels-nettoyage), le retour reste.';
COMMENT ON COLUMN public.appels_analyses."coach_id" IS 'Coach (ou CEO) qui a déposé l''appel ; reçoit les notifications ; = profiles.id.';
COMMENT ON COLUMN public.appels_analyses."eleve_id" IS 'Élève dont c''est l''appel ; = profiles.id.';
COMMENT ON COLUMN public.appels_analyses."type_appel" IS 'Type d''appel ; seule valeur autorisée : setting_ads (appel de setting d''un lead pub).';
COMMENT ON COLUMN public.appels_analyses."statut" IS 'depose = fichier envoyé, analyse pas lancée ; en_cours = machine au travail ; a_valider = analyse IA prête ; valide = validé par le coach ; erreur = échec (voir erreur).';
COMMENT ON COLUMN public.appels_analyses."etape" IS 'Étape en cours de la machine (demarrage, transcription…) ; null hors traitement.';
COMMENT ON COLUMN public.appels_analyses."fichier_path" IS 'Chemin du fichier déposé (bucket privé appels) ; mis à null quand l''audio est effacé.';
COMMENT ON COLUMN public.appels_analyses."audio_path" IS 'Chemin de l''audio converti ; mis à null quand l''audio est effacé.';
COMMENT ON COLUMN public.appels_analyses."duree_s" IS 'Durée de l''appel en secondes.';
COMMENT ON COLUMN public.appels_analyses."prospect_informe" IS 'Vrai si le prospect a été prévenu de l''enregistrement (coché ou détecté) ; sinon la note perd penalite_enregistrement points.';
COMMENT ON COLUMN public.appels_analyses."voix_inversees" IS 'Vrai si le coach a inversé élève et prospect (l''IA les avait confondus) ; relance l''analyse seule.';
COMMENT ON COLUMN public.appels_analyses."transcription" IS 'JSON {tours, mots} : tours de parole horodatés par voix (SETTER / PROSPECT).';
COMMENT ON COLUMN public.appels_analyses."mesures" IS 'JSON des mesures calculées : durée, temps de parole par voix, part du setter en %, silences après les questions.';
COMMENT ON COLUMN public.appels_analyses."analyse_ia" IS 'JSON du retour produit par l''IA (étapes notées sur 10, citations, points à travailler, fiche closer).';
COMMENT ON COLUMN public.appels_analyses."analyse_coach" IS 'JSON du retour corrigé par le coach ; null tant qu''il n''a rien enregistré. C''est la version qui fait foi.';
COMMENT ON COLUMN public.appels_analyses."note_ia" IS 'Note globale sur 100 proposée à la fin du traitement, calculée par le code avec les poids de la grille (pas par l''IA).';
COMMENT ON COLUMN public.appels_analyses."note_finale" IS 'Note sur 100 après corrections du coach (= note_ia tant qu''il n''a rien changé). Vue par le coach seulement depuis la v0.6.';
COMMENT ON COLUMN public.appels_analyses."nb_corrections" IS 'Nombre de corrections faites par le coach sur le retour de l''IA.';
COMMENT ON COLUMN public.appels_analyses."exemple_reference" IS 'Vrai si le coach a marqué ce retour validé comme modèle : les 4 plus récents sont joints aux instructions de l''IA.';
COMMENT ON COLUMN public.appels_analyses."referentiel_version" IS 'Version du référentiel utilisée (ex. 0.4, 0.6) ; voir appels_referentiels.version.';
COMMENT ON COLUMN public.appels_analyses."valide_par" IS 'Coach qui a validé ; = profiles.id. null si non validé ou rouvert.';
COMMENT ON COLUMN public.appels_analyses."valide_le" IS 'Date de validation ; null si non validé ou rouvert.';
COMMENT ON COLUMN public.appels_analyses."erreur" IS 'Message d''erreur du dernier échec (ex. machine interrompue après 30 min).';
COMMENT ON COLUMN public.appels_analyses."jeton_hash" IS 'Empreinte du jeton à usage unique donné à la machine d''analyse (masquée pour le connecteur).';
COMMENT ON COLUMN public.appels_analyses."lance_le" IS 'Dernier lancement (ou relance) de l''analyse.';
COMMENT ON COLUMN public.appels_analyses."audio_expire_le" IS 'Date prévue d''effacement de l''audio (dépôt + 30 jours).';
COMMENT ON COLUMN public.appels_analyses."audio_supprime_le" IS 'Date réelle d''effacement de l''audio ; null = audio encore présent.';
COMMENT ON COLUMN public.appels_analyses."cree_le" IS 'Date du dépôt.';
COMMENT ON COLUMN public.appels_analyses."maj_le" IS 'Dernière modification.';
COMMENT ON TABLE public.appels_referentiels IS 'Référentiel de notation d''un type d''appel, versionné (unique type_appel + version) : méthode, règles, script et grille de poids transmis à l''IA. Inséré directement en base par migration (le contenu n''est pas dans le dépôt public). La machine prend le plus récent avec actif = vrai ; depuis le 24/11/2026 c''est la v0.6 (format coach).';
COMMENT ON COLUMN public.appels_referentiels."type_appel" IS 'Type d''appel couvert ; seule valeur : setting_ads.';
COMMENT ON COLUMN public.appels_referentiels."version" IS 'Version du référentiel (0.3, 0.4, 0.5, 0.6…) ; reprise dans appels_analyses.referentiel_version.';
COMMENT ON COLUMN public.appels_referentiels."contenu" IS 'Texte de la méthode (règles, étapes, calibrage, script) envoyé tel quel à l''IA.';
COMMENT ON COLUMN public.appels_referentiels."grille" IS 'JSON [{code, nom, poids}] des étapes notées : la note sur 100 est calculée avec ces poids.';
COMMENT ON COLUMN public.appels_referentiels."penalite_enregistrement" IS 'Points retirés de la note sur 100 si le prospect n''a pas été prévenu de l''enregistrement (3 par défaut).';
COMMENT ON COLUMN public.appels_referentiels."duree_min_s" IS 'Durée normale minimale d''un appel, en secondes (alerte « trop court »).';
COMMENT ON COLUMN public.appels_referentiels."duree_max_s" IS 'Durée normale maximale d''un appel, en secondes (alerte « trop long »).';
COMMENT ON COLUMN public.appels_referentiels."actif" IS 'Vrai = version utilisable ; une seule active par type en pratique.';
COMMENT ON COLUMN public.appels_referentiels."format" IS 'Format du retour produit : v1 = ancien format détaillé noté ; coach = format de la coach (v0.6, sans note pour l''élève).';
COMMENT ON TABLE public.apporteur_invoices IS 'Une ligne = la facture mensuelle d''un bénéficiaire de commissions (apporteur, mais aussi closer, setter, coach) adressée à la plateforme. Générée par generate-apporteur-invoice : regroupe ses commissions ''due'' dont l''échéance est payée avant la fin du mois, + son salaire fixe éventuel (salary_periods). Montants en euros. Détail dans invoice_lines. Passer en paid marque les commissions liées en paid.';
COMMENT ON COLUMN public.apporteur_invoices."apporteur_id" IS 'Bénéficiaire facturant (profiles.id), quel que soit son rôle.';
COMMENT ON COLUMN public.apporteur_invoices."invoice_number" IS 'Numéro FACT-NNN-PRENOM-NOM-AAAAMM (compteur par bénéficiaire, période).';
COMMENT ON COLUMN public.apporteur_invoices."period_month" IS 'Mois facturé (1-12).';
COMMENT ON COLUMN public.apporteur_invoices."period_year" IS 'Année facturée.';
COMMENT ON COLUMN public.apporteur_invoices."total_amount" IS 'Total en euros = commissions incluses + salaire fixe du mois.';
COMMENT ON COLUMN public.apporteur_invoices."status" IS 'draft = brouillon ; generated = générée ; sent = envoyée ; paid = réglée au bénéficiaire.';
COMMENT ON COLUMN public.apporteur_invoices."paid_at" IS 'Date du règlement au bénéficiaire.';
COMMENT ON TABLE public.call_activities IS 'Journal des actions sur un call (une ligne par action), écrit depuis la fenêtre de traitement du call et par la fonction de changement de closer. Ajout seul.';
COMMENT ON COLUMN public.call_activities."call_id" IS 'Call concerné (calls.id).';
COMMENT ON COLUMN public.call_activities."user_id" IS 'Auteur de l''action (profiles.id).';
COMMENT ON COLUMN public.call_activities."action" IS 'status_change = changement de statut ; note_added = note du closer ; follow_up_reporte = date de follow-up modifiée ; reassigned = changement de closer.';
COMMENT ON COLUMN public.call_activities."old_value" IS 'Valeur avant (statut, date ou closer selon l''action).';
COMMENT ON COLUMN public.call_activities."new_value" IS 'Valeur après.';
COMMENT ON TABLE public.calls IS 'Un rendez-vous (call) avec un prospect, presque toujours créé par le webhook Calendly (webhook-calendly) ; les closers le traitent ensuite (statut, notes). Rattacher au prospect par contact_id : lead_id est souvent vide ou pointe une fiche parmi d''autres. Une annulation Calendly passe le call en annule ; un re-booking crée une nouvelle ligne (rescheduled_from). Pour compter les ventes, utiliser la table des ventes, pas status = close.';
COMMENT ON COLUMN public.calls."contact_id" IS 'Personne concernée (contacts.id). Clé de rattachement la plus fiable vers les leads et les ventes.';
COMMENT ON COLUMN public.calls."lead_id" IS 'Fiche lead au moment de la réservation (la plus récente du contact). Peut être NULL.';
COMMENT ON COLUMN public.calls."calendly_event_id" IS 'URI de l''évènement Calendly (unique par RDV). NULL pour un call créé hors Calendly.';
COMMENT ON COLUMN public.calls."event_type" IS 'Agenda d''origine. Codes actuels : inscription_conference, appel_vsl_tunnel, rediffusion_conference, tunnel_liberty, site_vitrine, al_baraka_200. Les libellés en MAJUSCULES sont d''anciens noms bruts.';
COMMENT ON COLUMN public.calls."scheduled_at" IS 'Date et heure du RDV (timestamptz, stocké en UTC ; convertir en Europe/Paris).';
COMMENT ON COLUMN public.calls."duration_minutes" IS 'Durée prévue du RDV en minutes (Calendly, 30 par défaut).';
COMMENT ON COLUMN public.calls."assigned_to" IS 'Closer qui tient le call (profiles.id), déduit de l''hôte Calendly ; modifiable via le bouton « Changer ».';
COMMENT ON COLUMN public.calls."status" IS 'planifie = à venir ou non traité ; annule ; no_show = absent ; pas_interesse ; disqualifie ; non_close = tenu sans vente ; renvoye_pole_vente ; renvoye_conference ; rediffusion ; follow_up ; close.';
COMMENT ON COLUMN public.calls."outcome" IS 'Ancien champ (vente / relance / perdu), plus écrit par l''appli. Usage à confirmer ; préférer status.';
COMMENT ON COLUMN public.calls."notes" IS 'Ancienne note générale du call (historique).';
COMMENT ON COLUMN public.calls."canceled_at" IS 'Date d''annulation (Calendly).';
COMMENT ON COLUMN public.calls."canceled_by" IS 'Qui a annulé côté Calendly : host = le closer ; invitee = le prospect ; unknown.';
COMMENT ON COLUMN public.calls."cancellation_reason" IS 'Motif d''annulation saisi dans Calendly.';
COMMENT ON COLUMN public.calls."rescheduled_from" IS 'Call annulé que ce RDV remplace (dernier call annulé du même contact) : un re-booking n''est pas un nouveau prospect.';
COMMENT ON COLUMN public.calls."raw_full_name" IS 'Nom tel que saisi dans Calendly (donnée personnelle).';
COMMENT ON COLUMN public.calls."raw_email" IS 'E-mail tel que saisi dans Calendly (donnée personnelle).';
COMMENT ON COLUMN public.calls."raw_phone" IS 'Téléphone tel que saisi dans Calendly (donnée personnelle).';
COMMENT ON COLUMN public.calls."closer_notes" IS 'Note du closer saisie dans la fenêtre de traitement du call.';
COMMENT ON COLUMN public.calls."conference_date" IS 'Conférence (dimanche) suivant la date du RDV, posée par trigger. Un call de rediffusion tombe sur la conférence suivante ; pour le marketing, suivre plutôt leads.conference_date.';
COMMENT ON COLUMN public.calls."follow_up_le" IS 'Date de relance d''un call en status follow_up (vidée quand il en sort).';
COMMENT ON VIEW public.calls_enriched IS 'Vue : calls_enriched_base filtrée selon le rôle de l''utilisateur connecté (CEO, collaborateur, agence : tout ; apporteur : calls de ses leads). Hors session applicative elle peut renvoyer 0 ligne : pour l''analyse, utiliser calls_enriched_base (mêmes colonnes).';
COMMENT ON VIEW public.calls_enriched_base IS 'Vue : calls + e-mail, téléphone et nom du contact, nom du closer et libellés français (event_type_label, status_label). Aucun filtre de droits : c''est la vue à utiliser pour l''analyse. Recalculée à chaque lecture.';
COMMENT ON COLUMN public.calls_enriched_base."contact_email" IS 'E-mail du contact (contacts.email).';
COMMENT ON COLUMN public.calls_enriched_base."contact_phone" IS 'Téléphone normalisé du contact (contacts.phone_normalized).';
COMMENT ON COLUMN public.calls_enriched_base."contact_full_name" IS 'Nom du contact.';
COMMENT ON COLUMN public.calls_enriched_base."assigned_to_name" IS 'Nom du closer (profiles.full_name).';
COMMENT ON COLUMN public.calls_enriched_base."event_type_label" IS 'Libellé français de l''agenda ; reprend le code brut s''il n''est pas prévu.';
COMMENT ON COLUMN public.calls_enriched_base."status_label" IS 'Libellé français du statut du call.';
COMMENT ON COLUMN public.calls_enriched_base."canceled_by_name" IS 'Nom de la personne qui a annulé (closer si host, contact si invitee).';
COMMENT ON TABLE public.card_update_links IS 'Une ligne = un lien « Changer de carte » (ALB-CARD-…) généré par le CEO depuis la fiche vente : le client met à jour sa carte sur un abonnement Stripe existant et l''échéance ouverte est rejouée. Valable 14 jours. Accès réservé au serveur.';
COMMENT ON COLUMN public.card_update_links."token" IS 'Jeton public ALB-CARD-… du lien (masquée pour le connecteur).';
COMMENT ON COLUMN public.card_update_links."contact_id" IS 'Client (contacts.id).';
COMMENT ON COLUMN public.card_update_links."sale_id" IS 'Vente concernée (sales.id).';
COMMENT ON COLUMN public.card_update_links."stripe_subscription_id" IS 'Abonnement Stripe dont la carte est changée.';
COMMENT ON COLUMN public.card_update_links."status" IS 'active = utilisable ; used = carte changée ; expired = expiré.';
COMMENT ON COLUMN public.card_update_links."created_by" IS 'Auteur (profil CEO).';
COMMENT ON COLUMN public.card_update_links."used_at" IS 'Date d''utilisation.';
COMMENT ON COLUMN public.card_update_links."expires_at" IS 'Expiration (création + 14 jours).';
COMMENT ON TABLE public.chapitre_progress IS 'Une ligne = un chapitre de formation terminé par un élève (formation_chapitres). Écrit par la RPC set_chapter_completion quand toutes les vidéos du chapitre sont vues ; la ligne est SUPPRIMÉE si l''élève décoche. Un déclencheur recopie la complétion vers les chapitres « jumeaux » (parcours_correspondances_chapitres) : un même travail peut donc compter dans deux formations.';
COMMENT ON COLUMN public.chapitre_progress."user_id" IS 'Élève (auth.users.id = profiles.id).';
COMMENT ON COLUMN public.chapitre_progress."chapitre_id" IS 'Chapitre terminé (formation_chapitres.id).';
COMMENT ON COLUMN public.chapitre_progress."completed_at" IS 'Moment de la complétion (ou de la recopie / reprise).';
COMMENT ON COLUMN public.chapitre_progress."time_spent_seconds" IS 'Temps passé en secondes : aucun code qui l''alimente trouvé, usage à confirmer (probablement 0).';
COMMENT ON TABLE public.chapitre_renvois IS 'Renvoi « pour aller plus loin » posé par le CEO : depuis un chapitre (ou une vidéo précise) vers un chapitre d''une autre formation (ou une vidéo précise). Contenu éditorial, aucune donnée élève.';
COMMENT ON COLUMN public.chapitre_renvois."chapitre_id" IS 'Chapitre de départ.';
COMMENT ON COLUMN public.chapitre_renvois."video_id" IS 'Vidéo de départ précise. Null = tout le chapitre.';
COMMENT ON COLUMN public.chapitre_renvois."cible_chapitre_id" IS 'Chapitre de destination (n''importe quelle formation).';
COMMENT ON COLUMN public.chapitre_renvois."cible_video_id" IS 'Vidéo de destination. Null = début du chapitre.';
COMMENT ON COLUMN public.chapitre_renvois."message" IS 'Phrase d''introduction facultative (280 caractères max).';
COMMENT ON TABLE public.chapitre_ressources IS 'Une ligne = une ressource (fichier, lien) attachée à un chapitre de formation, éventuellement à une vidéo. Alimente l''espace Ressources. Contenu éditorial.';
COMMENT ON COLUMN public.chapitre_ressources."type" IS 'fichier = fichier déposé dans le stockage ; link = lien externe ; pdf, image, video, doc, other = anciennes valeurs permises.';
COMMENT ON COLUMN public.chapitre_ressources."url" IS 'Adresse du fichier ou du lien.';
COMMENT ON COLUMN public.chapitre_ressources."video_id" IS 'Vidéo à laquelle la ressource est rattachée. Null = ressource du chapitre.';
COMMENT ON COLUMN public.chapitre_ressources."rubrique" IS 'script_interne = script interne AL BARAKA ; script_template = script modèle ; null = autre ressource (support, fiche…).';
COMMENT ON TABLE public.chapitre_videos IS 'Une ligne = une vidéo d''un chapitre de formation (hébergée sur Vimeo). Un chapitre peut avoir plusieurs vidéos ; il est terminé quand toutes sont vues (video_progress).';
COMMENT ON COLUMN public.chapitre_videos."url" IS 'Lien de la vidéo (Vimeo).';
COMMENT ON COLUMN public.chapitre_videos."vimeo_id" IS 'Identifiant Vimeo.';
COMMENT ON COLUMN public.chapitre_videos."duree_secondes" IS 'Durée de la vidéo en secondes (peut être null).';
COMMENT ON COLUMN public.chapitre_videos."notes" IS 'Notes affichées sous la vidéo (éditeur de chapitre).';
COMMENT ON TABLE public.client_contracts IS 'Une ligne = le contrat d''une vente (sale_id unique), surtout Pass AL BARAKA/Liberty et modules à la carte. Créé par stripe-webhook au paiement. Ancien circuit : signature dessinée (pending_signature → signed). Depuis le 13/11/2026 (v3) : le paiement vaut signature, contrat créé ''signed'' avec PDF unique contrat + attestation + CGV. Montants en euros TTC (TVA non applicable). Données client figées (personnelles).';
COMMENT ON COLUMN public.client_contracts."contract_number" IS 'Numéro CTR-AAAA-MM-NNNN (v3 : préfixé, ex. ALB-PASS-CTR-…).';
COMMENT ON COLUMN public.client_contracts."sale_id" IS 'Vente (sales.id), unique.';
COMMENT ON COLUMN public.client_contracts."template_key" IS 'Modèle : pass_standard / pass_conference (avec code conférence), liberty_standard / liberty_conference (ancien circuit) ; pass_v3, liberty_v3, carte_v3 (depuis le 13/11/2026).';
COMMENT ON COLUMN public.client_contracts."amount_total" IS 'Prix net à payer en euros, remise déduite.';
COMMENT ON COLUMN public.client_contracts."amount_original" IS 'Prix catalogue barré en euros.';
COMMENT ON COLUMN public.client_contracts."discount_amount" IS 'Remise en euros.';
COMMENT ON COLUMN public.client_contracts."coupon_code" IS 'Code promo utilisé.';
COMMENT ON COLUMN public.client_contracts."payment_modality" IS 'Texte de la modalité (ex. « Comptant », « 5 × 600,00 € »).';
COMMENT ON COLUMN public.client_contracts."installments_count" IS 'Nombre d''échéances prévues au contrat.';
COMMENT ON COLUMN public.client_contracts."first_payment_date" IS 'Date du premier paiement.';
COMMENT ON COLUMN public.client_contracts."agreements_snapshot" IS 'Engagements cochés avant paiement (JSON : id, texte, coché, date).';
COMMENT ON COLUMN public.client_contracts."status" IS 'pending_signature = en attente de signature (ancien circuit) ; signed = signé (ou payé en v3) ; voided = annulé.';
COMMENT ON COLUMN public.client_contracts."signed_at" IS 'Date de signature (v3 : date du paiement).';
COMMENT ON COLUMN public.client_contracts."signature_ip" IS 'IP de signature (preuve, donnée personnelle).';
COMMENT ON COLUMN public.client_contracts."signature_user_agent" IS 'Navigateur de signature (preuve).';
COMMENT ON COLUMN public.client_contracts."email_sent_at" IS 'Envoi du contrat au client.';
COMMENT ON COLUMN public.client_contracts."last_error" IS 'Dernière erreur de génération/envoi ; NULL = OK.';
COMMENT ON COLUMN public.client_contracts."email_resend_id" IS 'Identifiant de l''e-mail chez Resend (preuve d''envoi).';
COMMENT ON TABLE public.client_invoices IS 'Une ligne = une facture client FAC-AAAA-MM-NNNN émise pour UNE échéance encaissée (1 facture par paiement, payment_id unique). Générée par l''edge function generate-client-invoice après paiement (Stripe, saisie, acompte, Studio), envoyée par e-mail. Émetteur hors UE : TVA 0 %, montant HT = TTC en euros. Pas d''avoirs : un remboursement n''apparaît pas ici. Données client figées à l''émission.';
COMMENT ON COLUMN public.client_invoices."invoice_number" IS 'Numéro FAC-AAAA-MM-NNNN, séquence remise à zéro chaque mois.';
COMMENT ON COLUMN public.client_invoices."payment_id" IS 'Échéance facturée (payments.id), unique.';
COMMENT ON COLUMN public.client_invoices."sale_id" IS 'Vente (sales.id).';
COMMENT ON COLUMN public.client_invoices."contact_id" IS 'Client (contacts.id).';
COMMENT ON COLUMN public.client_invoices."client_name" IS 'Nom du client figé à l''émission (donnée personnelle).';
COMMENT ON COLUMN public.client_invoices."amount" IS 'Montant facturé en euros, TVA 0 % (HT = TTC) = montant de l''échéance.';
COMMENT ON COLUMN public.client_invoices."payment_number" IS 'Rang de l''échéance facturée.';
COMMENT ON COLUMN public.client_invoices."total_payments" IS 'Nombre d''échéances de la vente à l''émission.';
COMMENT ON COLUMN public.client_invoices."product" IS 'Libellé du produit sur la facture.';
COMMENT ON COLUMN public.client_invoices."paid_at" IS 'Date d''encaissement facturée (sert au tri « factures du mois » du comptable).';
COMMENT ON COLUMN public.client_invoices."html_path" IS 'Chemin du fichier HTML dans le stockage ''invoices''.';
COMMENT ON COLUMN public.client_invoices."pdf_url" IS 'Lien du PDF généré.';
COMMENT ON COLUMN public.client_invoices."email_sent_at" IS 'Envoi de la facture au client ; NULL = pas envoyée.';
COMMENT ON COLUMN public.client_invoices."email_sent_to" IS 'Adresse d''envoi (donnée personnelle).';
COMMENT ON COLUMN public.client_invoices."created_by" IS 'Auteur si création manuelle (profiles.id) ; NULL = automatique.';
COMMENT ON TABLE public.closing_daily_logs IS 'Une ligne = la journée d''entraînement closing d''un élève (onglet Vente de « Mon Activité ») : nombre de role plays faits, émotions, ressenti. Rattachée au plan closing de l''élève. Unique (plan_id, entry_date).';
COMMENT ON COLUMN public.closing_daily_logs."plan_id" IS 'Plan closing de l''élève (closing_plans.id) ; joindre closing_plans pour avoir user_id.';
COMMENT ON COLUMN public.closing_daily_logs."rp_d" IS 'Role plays d''appel découverte faits ce jour (« RP Découverte », objectif 4/jour).';
COMMENT ON COLUMN public.closing_daily_logs."rp_c" IS 'Role plays de closing faits ce jour (« RP Closing », objectif 3/jour).';
COMMENT ON COLUMN public.closing_daily_logs."emotions" IS 'Émotions cochées par l''élève (liste de libellés).';
COMMENT ON COLUMN public.closing_daily_logs."feeling" IS 'Ressenti libre de la journée.';
COMMENT ON COLUMN public.closing_daily_logs."learning" IS 'Apprentissage libre de la journée.';
COMMENT ON TABLE public.closing_plan90 IS 'Plan 90 jours closing (page /working/plan90) : UNE ligne par élève, tout le suivi (12 semaines × 7 jours) dans un JSON. Outil d''entraînement, distinct de closing_plans et du suivi activity_*.';
COMMENT ON COLUMN public.closing_plan90."user_id" IS 'Élève (auth.users.id).';
COMMENT ON COLUMN public.closing_plan90."data" IS 'État complet du plan 90 jours (structure propre à la page, à déplier en JSON).';
COMMENT ON TABLE public.closing_plans IS 'Une ligne = un plan closing de 90 jours d''un élève. Créé automatiquement à l''activation d''un Pass (déclencheur sur user_passes), mis en pause au retrait du pass, réactivé s''il a moins de 90 jours. Au plus un plan active par élève ; les anciens restent.';
COMMENT ON COLUMN public.closing_plans."user_id" IS 'Élève (profiles.id).';
COMMENT ON COLUMN public.closing_plans."pass_type" IS 'Pass qui a créé le plan : al_baraka ou liberty.';
COMMENT ON COLUMN public.closing_plans."started_at" IS 'Date de début du plan (heure de Paris).';
COMMENT ON COLUMN public.closing_plans."targets" IS 'Objectifs quotidiens de role plays, JSON {rp_d: découverte, rp_c: closing} ; défaut 4 et 3.';
COMMENT ON COLUMN public.closing_plans."status" IS 'active = plan en cours ; paused = pass retiré ; completed = terminé (valeur prévue, usage à confirmer).';
COMMENT ON TABLE public.coach_criteria IS 'Grille de coaching : une ligne = un critère noté (1 à 5) dans une étape (coach_steps) d''un type de coaching. Configuré par le CEO dans le constructeur de coaching.';
COMMENT ON COLUMN public.coach_criteria."step_id" IS 'Étape (coach_steps.id).';
COMMENT ON COLUMN public.coach_criteria."criteria_text" IS 'Libellé du critère.';
COMMENT ON COLUMN public.coach_criteria."is_active" IS 'Faux = critère retiré de la grille.';
COMMENT ON TABLE public.coach_debrief_options IS 'Grille de coaching : questions de débrief à choix proposées au coach pour une étape (coach_steps).';
COMMENT ON COLUMN public.coach_debrief_options."debrief_label" IS 'Question de débrief.';
COMMENT ON COLUMN public.coach_debrief_options."options" IS 'Réponses possibles proposées au coach.';
COMMENT ON TABLE public.coach_script_refs IS 'Grille de coaching : extraits du script de référence affichés au coach pour une étape, éventuellement selon le sous-mode (ex. appel découverte Ads ou Organique).';
COMMENT ON COLUMN public.coach_script_refs."sub_mode" IS 'Sous-mode concerné (ex. « Appel découverte Ads »). Null = tous.';
COMMENT ON COLUMN public.coach_script_refs."script_lines" IS 'Lignes du script de référence.';
COMMENT ON COLUMN public.coach_script_refs."script_content" IS 'Texte du script en un bloc (version plus récente que script_lines, usage à confirmer).';
COMMENT ON TABLE public.coach_steps IS 'Grille de coaching : une ligne = une étape d''un type de coaching (ex. ouverture, découverte, closing), avec objectif et conseils. Les notes des séances sont données par étape (coaching_scores).';
COMMENT ON COLUMN public.coach_steps."coach_type_id" IS 'Type de coaching (coach_types.id).';
COMMENT ON COLUMN public.coach_steps."step_number" IS 'Numéro de l''étape dans le type.';
COMMENT ON COLUMN public.coach_steps."step_id" IS 'Code texte de l''étape (identifiant lisible).';
COMMENT ON COLUMN public.coach_steps."tips" IS 'Conseils affichés au coach.';
COMMENT ON COLUMN public.coach_steps."is_active" IS 'Faux = étape retirée de la grille.';
COMMENT ON TABLE public.coach_type_assignments IS 'Coachs habilités sur un type de coaching (plusieurs coachs possibles par type). Géré dans Admin coaching > Coachs. Table créée hors migrations versionnées.';
COMMENT ON COLUMN public.coach_type_assignments."coach_id" IS 'Coach (profiles.id).';
COMMENT ON COLUMN public.coach_type_assignments."is_primary" IS 'Vrai = coach principal du type.';
COMMENT ON TABLE public.coach_types IS 'Types de coaching individuel noté (ex. Setting, Closing) : chaque type a sa grille (coach_steps → coach_criteria). Configuré par le CEO. Malgré le préfixe coach_, ce ne sont pas des coachs IA mais des grilles pour coachs humains.';
COMMENT ON COLUMN public.coach_types."name" IS 'Code unique du type.';
COMMENT ON COLUMN public.coach_types."label" IS 'Libellé affiché.';
COMMENT ON COLUMN public.coach_types."theme_color" IS 'Couleur d''affichage.';
COMMENT ON COLUMN public.coach_types."theme_bg" IS 'Couleur de fond d''affichage.';
COMMENT ON COLUMN public.coach_types."assigned_coach_id" IS 'Ancien coach unique du type (profiles.id) ; voir aussi coach_type_assignments.';
COMMENT ON COLUMN public.coach_types."sub_modes" IS 'Sous-modes proposés à la création d''une séance (ex. Setting RDV, Setting Conférence, Appel découverte Ads).';
COMMENT ON TABLE public.coaching_attendance IS 'Une ligne = un élève a cliqué « Rejoindre » sur une séance de coaching collectif (coaching_occurrences). C''est un clic, pas une présence vérifiée sur la visio. Unique (user_id, occurrence_id).';
COMMENT ON COLUMN public.coaching_attendance."user_id" IS 'Élève (profiles.id).';
COMMENT ON COLUMN public.coaching_attendance."occurrence_id" IS 'Séance (coaching_occurrences.id).';
COMMENT ON COLUMN public.coaching_attendance."joined_at" IS 'Heure du clic.';
COMMENT ON TABLE public.coaching_occurrences IS 'Une ligne = une séance réelle d''un coaching collectif hebdomadaire (créneau coaching_weekly_slots à une date). Créée à la demande (RPC ensure_coaching_occurrence) au premier clic ou à l''ajout du replay : une semaine sans clic ni replay n''a pas de ligne. Unique (slot_id, occurrence_date).';
COMMENT ON COLUMN public.coaching_occurrences."slot_id" IS 'Créneau hebdomadaire (coaching_weekly_slots.id, slug texte, sans clé étrangère).';
COMMENT ON COLUMN public.coaching_occurrences."occurrence_date" IS 'Date de la séance (Paris).';
COMMENT ON COLUMN public.coaching_occurrences."started_at" IS 'Début de la séance (horodatage).';
COMMENT ON COLUMN public.coaching_occurrences."duration_minutes" IS 'Durée prévue en minutes.';
COMMENT ON COLUMN public.coaching_occurrences."replay_url" IS 'Lien du replay. Null = pas de replay.';
COMMENT ON COLUMN public.coaching_occurrences."replay_password" IS 'Mot de passe du replay (masquée pour le connecteur).';
COMMENT ON COLUMN public.coaching_occurrences."replay_added_at" IS 'Ajout du replay (rempli par déclencheur).';
COMMENT ON COLUMN public.coaching_occurrences."replay_available_until" IS 'Fin de disponibilité du replay : ajout + 30 jours.';
COMMENT ON TABLE public.coaching_replay_views IS 'Une ligne = un élève a ouvert le replay d''une séance de coaching. Dédoublonné : une seule ligne par élève et séance (première ouverture).';
COMMENT ON COLUMN public.coaching_replay_views."user_id" IS 'Élève (profiles.id).';
COMMENT ON COLUMN public.coaching_replay_views."occurrence_id" IS 'Séance (coaching_occurrences.id).';
COMMENT ON COLUMN public.coaching_replay_views."viewed_at" IS 'Première ouverture du replay.';
COMMENT ON TABLE public.coaching_reservations IS 'Une ligne = une réservation Calendly de coaching individuel payant (offre /checkout/coaching), reçue par l''edge function webhook-calendly. Ces RDV ne sont pas dans calls. paye = rattachée à un paiement ; sinon une alerte part au CEO.';
COMMENT ON COLUMN public.coaching_reservations."calendly_event_uri" IS 'Identifiant Calendly de l''évènement (unique).';
COMMENT ON COLUMN public.coaching_reservations."offre_coaching" IS 'Offre (offres_coaching.slug).';
COMMENT ON COLUMN public.coaching_reservations."payment_link_id" IS 'Lien de paiement utilisé (payment_links.id).';
COMMENT ON COLUMN public.coaching_reservations."sale_id" IS 'Vente correspondante (sales.id).';
COMMENT ON COLUMN public.coaching_reservations."contact_id" IS 'Élève côté CRM (contacts.id).';
COMMENT ON COLUMN public.coaching_reservations."coach_id" IS 'Coach (profiles.id).';
COMMENT ON COLUMN public.coaching_reservations."invitee_nom" IS 'Nom saisi sur Calendly (donnée personnelle).';
COMMENT ON COLUMN public.coaching_reservations."invitee_email" IS 'E-mail saisi sur Calendly (donnée personnelle).';
COMMENT ON COLUMN public.coaching_reservations."scheduled_at" IS 'Date et heure du coaching réservé.';
COMMENT ON COLUMN public.coaching_reservations."statut" IS 'planifie = réservation active ; annule = annulée sur Calendly (voir annule_le).';
COMMENT ON COLUMN public.coaching_reservations."paye" IS 'Vrai = rattachée à un paiement de coaching.';
COMMENT ON TABLE public.coaching_scores IS 'Une ligne = les notes d''une étape (coach_steps) dans une séance de coaching individuel (coaching_sessions). Unique (session_id, step_id). Un déclencheur recalcule coaching_sessions.global_score à chaque écriture.';
COMMENT ON COLUMN public.coaching_scores."criteria_scores" IS 'Notes de 1 à 5 par critère, dans l''ordre des critères de l''étape ; 0 = non noté (ignoré dans les moyennes).';
COMMENT ON COLUMN public.coaching_scores."debrief_responses" IS 'Réponses choisies aux questions de débrief (coach_debrief_options).';
COMMENT ON COLUMN public.coaching_scores."notes" IS 'Commentaire libre du coach.';
COMMENT ON TABLE public.coaching_sessions IS 'Une ligne = une séance de coaching individuel notée par un coach humain pour un élève (grille coach_types). Saisie dans Coaching > séances ; l''élève la voit dans « Mon coaching ». Peu de lignes.';
COMMENT ON COLUMN public.coaching_sessions."coach_user_id" IS 'Coach (profiles.id).';
COMMENT ON COLUMN public.coaching_sessions."student_user_id" IS 'Élève coaché (profiles.id).';
COMMENT ON COLUMN public.coaching_sessions."sub_mode" IS 'Sous-mode : Setting RDV, Setting Conférence, Appel découverte Ads…';
COMMENT ON COLUMN public.coaching_sessions."session_number" IS 'Numéro de séance de l''élève (1, 2, 3…).';
COMMENT ON COLUMN public.coaching_sessions."global_score" IS 'Moyenne sur 5 de toutes les notes > 0 de la séance (calculée par déclencheur). Null = rien noté.';
COMMENT ON COLUMN public.coaching_sessions."status" IS 'draft = séance en cours de saisie ; completed = séance finalisée.';
COMMENT ON COLUMN public.coaching_sessions."structure_snapshot" IS 'Copie de la grille au moment de la séance (pour l''historique si la grille change).';
COMMENT ON TABLE public.coaching_weekly_slots IS 'Les coachings collectifs hebdomadaires récurrents (ex. Setting Téléphonique, Créa de contenus, Setting Message, Closing) : jour, heure, coach. Source de vérité du calendrier depuis le 14/05/2026. Quelques lignes.';
COMMENT ON COLUMN public.coaching_weekly_slots."id" IS 'Slug du créneau (ex. setting-telephonique) ; repris dans coaching_occurrences.slot_id.';
COMMENT ON COLUMN public.coaching_weekly_slots."day" IS 'Jour de la semaine en français (Lundi…Dimanche).';
COMMENT ON COLUMN public.coaching_weekly_slots."hour" IS 'Heure de début, heure de Paris.';
COMMENT ON COLUMN public.coaching_weekly_slots."minute" IS 'Minute de début.';
COMMENT ON COLUMN public.coaching_weekly_slots."coach" IS 'Prénom du coach affiché (texte libre, pas une clé).';
COMMENT ON COLUMN public.coaching_weekly_slots."coach_type_id" IS 'Type de coaching associé (coach_types.id).';
COMMENT ON COLUMN public.coaching_weekly_slots."formation_requise_id" IS 'Formation à terminer pour accéder au créneau. Null = créneau libre.';
COMMENT ON TABLE public.commissions IS 'Une ligne = la commission d''un bénéficiaire (rôle) sur UNE échéance d''une vente. Montant = échéance × taux, en euros. Posée à la main par le CEO sur la vente (éclatée par échéance), ou automatiquement (setter DM 5 %, coach). Suit le statut de l''échéance. Pour la commission d''une vente : sommer toutes ses lignes. Source de référence pour savoir qui a closé ou setté une vente.';
COMMENT ON COLUMN public.commissions."sale_id" IS 'Vente commissionnée (sales.id).';
COMMENT ON COLUMN public.commissions."beneficiary_user_id" IS 'Bénéficiaire membre de l''équipe (profiles.id). Exclusif avec beneficiary_external.';
COMMENT ON COLUMN public.commissions."beneficiary_external" IS 'Nom d''un bénéficiaire externe sans compte (ex. agence). Exclusif avec beneficiary_user_id.';
COMMENT ON COLUMN public.commissions."percentage" IS 'Taux en % (ex. 10 = 10 %) appliqué au montant de l''échéance.';
COMMENT ON COLUMN public.commissions."amount" IS 'Commission en euros = round(payments.amount × percentage / 100, 2).';
COMMENT ON COLUMN public.commissions."role" IS 'apporteur = a apporté le lead ; setter = a qualifié/booké (dont setter DM auto 5 %) ; closer = a vendu en call ; coach = coaching individuel ; agence_marketing = agence pub.';
COMMENT ON COLUMN public.commissions."status" IS 'pending = échéance pas encore payée ; due = échéance payée, à verser ; invoiced = incluse dans une facture bénéficiaire ; paid = versée ; cancelled = échéance perdue.';
COMMENT ON COLUMN public.commissions."paid_at" IS 'Date de versement de la commission au bénéficiaire (pas la date de paiement du client).';
COMMENT ON COLUMN public.commissions."payment_id" IS 'Échéance concernée (payments.id). NULL = commission globale pas encore répartie (rare).';
COMMENT ON TABLE public.commissions_backup_20260701 IS 'Sauvegarde/Obsolète — ne pas utiliser pour l''analyse. Copie de la table commissions prise le 01/07/2026 avant une correction. Aucune clé étrangère, aucun usage dans le code ; accès fermé à l''API depuis le 11/11/2026.';
COMMENT ON TABLE public.conference_envois_alertes IS 'Alertes à envoyer à l''équipe sur les envois de conférence (étape bloquée, trop tard, échec). Écrites par tick_envois_conference, expédiées aux témoins par l''edge function alerte-conference.';
COMMENT ON COLUMN public.conference_envois_alertes."sujet" IS 'Objet de l''alerte.';
COMMENT ON COLUMN public.conference_envois_alertes."message" IS 'Texte de l''alerte.';
COMMENT ON COLUMN public.conference_envois_alertes."envoye_a" IS 'Moment de l''envoi de l''alerte ; NULL = en attente.';
COMMENT ON COLUMN public.conference_envois_alertes."erreur" IS 'Erreur rencontrée à l''envoi de l''alerte.';
COMMENT ON TABLE public.conference_envois_journal IS 'Journal des envois automatiques d''une conférence : une ligne par conférence et par étape (mail ou SMS), réservée avant l''appel pour éviter les doublons. Écrit par tick_envois_conference (cron chaque minute). Ne contient pas le nombre de destinataires. Plusieurs étapes présentes en base ne figurent pas dans les migrations (planning modifié en production).';
COMMENT ON COLUMN public.conference_envois_journal."conference_date" IS 'Conférence concernée (conferences.conference_date).';
COMMENT ON COLUMN public.conference_envois_journal."etape" IS 'Étape du planning : ex. j1_rappel (mail J-1 19h), m30, m10 (SMS), ouverture, m15 (SMS), post_dimanche, post_j1..post_j3_soir, nurturing_j2..j5, h2… Liste complète à confirmer.';
COMMENT ON COLUMN public.conference_envois_journal."canal" IS 'mail ou sms.';
COMMENT ON COLUMN public.conference_envois_journal."seq" IS 'Numéro de séquence passé à l''edge function d''envoi (send-conference-mail / send-conference-sms).';
COMMENT ON COLUMN public.conference_envois_journal."prevu_a" IS 'Heure prévue de l''étape (calculée en heure de Paris, stockée en UTC).';
COMMENT ON COLUMN public.conference_envois_journal."declenche_a" IS 'Heure réelle du déclenchement.';
COMMENT ON COLUMN public.conference_envois_journal."statut" IS 'declenche = appel lancé ; fait = envoi confirmé ; echec = erreur ; bloque = non envoyé (ex. groupe WhatsApp absent) ; trop_tard = fenêtre dépassée, non envoyé.';
COMMENT ON COLUMN public.conference_envois_journal."request_id" IS 'Identifiant de la requête HTTP (pg_net) qui a appelé l''edge function.';
COMMENT ON COLUMN public.conference_envois_journal."detail" IS 'Explication en cas de blocage, retard ou échec.';
COMMENT ON COLUMN public.conference_envois_journal."verifie_a" IS 'Moment où le résultat de l''appel a été vérifié.';
COMMENT ON TABLE public.conference_envois_temoins IS 'Adresses et numéros de l''équipe insérés en tête de chaque envoi de conférence (contrôle de réception). Saisis directement en base. Ce ne sont pas des prospects : à exclure des comptages.';
COMMENT ON COLUMN public.conference_envois_temoins."canal" IS 'mail ou sms.';
COMMENT ON COLUMN public.conference_envois_temoins."valeur" IS 'Adresse e-mail (canal mail) ou téléphone +33… (canal sms) du témoin.';
COMMENT ON COLUMN public.conference_envois_temoins."email" IS 'Pour un témoin SMS : e-mail associé (colonne requise par les listes SMS).';
COMMENT ON COLUMN public.conference_envois_temoins."prenom" IS 'Prénom utilisé dans les messages.';
COMMENT ON TABLE public.conferences IS 'Une conférence (webinaire du dimanche, une ligne par date). Créées à l''avance, complétées dans /admin/conferences : salle Zoom, groupe WhatsApp, vidéos, replay. Pilote les envois automatiques (tick_envois_conference) et la page de rediffusion /redif/:token. Les leads, calls et ventes s''y rattachent par conference_date (pas de clé étrangère).';
COMMENT ON COLUMN public.conferences."conference_date" IS 'Date du dimanche de la conférence (unique). Clé de jointure avec leads/calls/ventes.conference_date.';
COMMENT ON COLUMN public.conferences."token" IS 'Jeton du lien public de rediffusion /redif/:token (masquée pour le connecteur).';
COMMENT ON COLUMN public.conferences."status" IS 'scheduled = replay pas encore prêt ; ready = replay complet, lien partageable (posé automatiquement) ; archived = archivée.';
COMMENT ON COLUMN public.conferences."replay_url" IS 'Lien de la vidéo de rediffusion.';
COMMENT ON COLUMN public.conferences."replay_code" IS 'Code d''accès au replay affiché au prospect.';
COMMENT ON COLUMN public.conferences."video_duration_min" IS 'Durée de la vidéo de rediffusion, en minutes.';
COMMENT ON COLUMN public.conferences."calendly_url" IS 'Lien de prise de RDV proposé après la rediffusion.';
COMMENT ON COLUMN public.conferences."ready_at" IS 'Moment où la rediffusion est devenue prête.';
COMMENT ON COLUMN public.conferences."starts_at_local" IS 'Heure de début, heure de Paris. NULL = 11h00. C''est aussi l''heure où les nouvelles inscriptions basculent sur la conférence suivante.';
COMMENT ON COLUMN public.conferences."envois_auto" IS 'Vrai : mails et SMS partent automatiquement. Faux pour les conférences programmées à la main (jusqu''au 13/09/2026).';
COMMENT ON VIEW public.consentement_marketing_actuel IS 'Vue : dernier état du consentement marketing par adresse e-mail (une ligne par e-mail, la réponse la plus récente de consentements_marketing). À utiliser pour savoir qui peut recevoir des envois commerciaux.';
COMMENT ON COLUMN public.consentement_marketing_actuel."email" IS 'Adresse e-mail en minuscules.';
COMMENT ON COLUMN public.consentement_marketing_actuel."consenti" IS 'Dernière réponse connue : vrai = consent ; faux = refus ou retrait.';
COMMENT ON COLUMN public.consentement_marketing_actuel."origine" IS 'Formulaire de la dernière réponse (tunnel_optin, rdv, quiz).';
COMMENT ON COLUMN public.consentement_marketing_actuel."created_at" IS 'Date de la dernière réponse.';
COMMENT ON TABLE public.consentements_marketing IS 'Journal RGPD du consentement à la prospection par e-mail : une ligne par réponse à la case (oui ou non), en ajout seul ; un retrait est une nouvelle ligne consenti = false. Écrit par tunnel-lead-submit, rdv-funnel-submit et submit-quiz-lead. Pas de lien vers leads/contacts : relier par e-mail en minuscules. Pas de ligne = pas de consentement (cas du site vitrine).';
COMMENT ON COLUMN public.consentements_marketing."email" IS 'Adresse concernée (en minuscules). Donnée personnelle.';
COMMENT ON COLUMN public.consentements_marketing."consenti" IS 'Vrai = a coché la case ; faux = ne l''a pas cochée ou s''est rétracté.';
COMMENT ON COLUMN public.consentements_marketing."origine" IS 'Formulaire : tunnel_optin = inscription aux tunnels ; rdv = formulaire de rendez-vous /rdv ; quiz = quiz apporteur.';
COMMENT ON COLUMN public.consentements_marketing."page" IS 'Page affichée au moment de la réponse.';
COMMENT ON COLUMN public.consentements_marketing."libelle" IS 'Texte exact de la case soumis à la personne.';
COMMENT ON COLUMN public.consentements_marketing."adresse_ip" IS 'Adresse IP de la personne (preuve). Donnée personnelle.';
COMMENT ON COLUMN public.consentements_marketing."navigateur" IS 'User-agent du navigateur (preuve).';
COMMENT ON TABLE public.contact_identifiers IS 'Identifiants servant au dédoublonnage des contacts : une ligne par e-mail, téléphone E.164 et 9 derniers chiffres du téléphone d''un contact. Alimentée par find_or_create_contact. Table technique, pas pour compter.';
COMMENT ON COLUMN public.contact_identifiers."contact_id" IS 'Contact (contacts.id).';
COMMENT ON COLUMN public.contact_identifiers."identifier_type" IS 'email ; phone = téléphone E.164 ; phone_short = 9 derniers chiffres du téléphone (rapproche +33 6… et 06…).';
COMMENT ON COLUMN public.contact_identifiers."identifier_value" IS 'Valeur de l''identifiant (unique par type). Donnée personnelle.';
COMMENT ON TABLE public.contacts IS 'Une personne physique, dédoublonnée par e-mail et téléphone (fonction find_or_create_contact, appelée par tous les formulaires et webhooks). Une personne peut avoir plusieurs fiches leads, calls et ventes : compter les personnes avec contacts.id ou leads.contact_id distincts.';
COMMENT ON COLUMN public.contacts."email" IS 'E-mail en minuscules (unique). Donnée personnelle.';
COMMENT ON COLUMN public.contacts."phone_normalized" IS 'Téléphone au format international E.164 (+33…). Donnée personnelle.';
COMMENT ON COLUMN public.contacts."phone_original" IS 'Téléphone tel que saisi la première fois.';
COMMENT ON COLUMN public.contacts."full_name" IS 'Nom complet en MAJUSCULES (dernier nom reçu). Donnée personnelle.';
COMMENT ON COLUMN public.contacts."payment_code" IS 'Code de paiement personnel ALB-XXXXXX, créé au 1er acompte payé, utilisé dans le lien de checkout (?code=). NULL sans acompte.';
COMMENT ON TABLE public.contacts_phone_backup_20260418 IS 'Sauvegarde/Obsolète — ne pas utiliser pour l''analyse. Copie des téléphones de contacts avant la normalisation E.164 du 18/04/2026.';
COMMENT ON COLUMN public.contacts_phone_backup_20260418."phone_normalized" IS 'Valeur avant normalisation.';
COMMENT ON COLUMN public.contacts_phone_backup_20260418."phone_original" IS 'Valeur saisie d''origine.';
COMMENT ON COLUMN public.contacts_phone_backup_20260418."backup_at" IS 'Date de la sauvegarde.';
COMMENT ON TABLE public.coupons IS 'Une ligne = un code promo utilisable au checkout ou sur un lien de paiement, validé par validate_coupon. Remise en % ou en euros fixes, ciblée par offre ou catégorie. Pour compter les utilisations, compter sales.coupon_code (times_redeemed n''est pas incrémenté par le code versionné).';
COMMENT ON COLUMN public.coupons."code" IS 'Code saisi par le client.';
COMMENT ON COLUMN public.coupons."discount_percent" IS 'Remise en % (si discount_type = percent).';
COMMENT ON COLUMN public.coupons."stripe_coupon_id" IS 'Coupon Stripe associé (ancien circuit).';
COMMENT ON COLUMN public.coupons."active" IS 'false = code désactivé.';
COMMENT ON COLUMN public.coupons."expires_at" IS 'Date d''expiration ; NULL = sans limite.';
COMMENT ON COLUMN public.coupons."max_redemptions" IS 'Plafond d''utilisations ; NULL = illimité.';
COMMENT ON COLUMN public.coupons."times_redeemed" IS 'Compteur d''utilisations : jamais incrémenté par le code versionné, ne pas s''y fier.';
COMMENT ON COLUMN public.coupons."discount_type" IS 'percent = remise en % ; fixed_eur = remise fixe en euros.';
COMMENT ON COLUMN public.coupons."discount_amount_eur" IS 'Remise fixe en euros (si discount_type = fixed_eur).';
COMMENT ON COLUMN public.coupons."applies_to_offer_ids" IS 'Offres ciblées (offers.id).';
COMMENT ON COLUMN public.coupons."applies_to_categories" IS 'Catégories d''offres ciblées (al_baraka, al_baraka_200, liberty, a_la_carte).';
COMMENT ON TABLE public.discord_links IS 'Liaison entre un compte plateforme et son compte Discord (une ligne par utilisateur), créée par OAuth Discord ou par l''admin. Sert à donner les rôles Discord des formations.';
COMMENT ON COLUMN public.discord_links."user_id" IS 'Compte plateforme (profiles.id), clé primaire.';
COMMENT ON COLUMN public.discord_links."discord_user_id" IS 'Identifiant Discord.';
COMMENT ON COLUMN public.discord_links."discord_username" IS 'Pseudo Discord.';
COMMENT ON COLUMN public.discord_links."discord_global_name" IS 'Nom affiché Discord.';
COMMENT ON COLUMN public.discord_links."discord_avatar" IS 'Avatar Discord.';
COMMENT ON COLUMN public.discord_links."is_guild_member" IS 'true = membre du serveur Discord Al Baraka (dernière vérification).';
COMMENT ON COLUMN public.discord_links."linked_at" IS 'Date de liaison.';
COMMENT ON COLUMN public.discord_links."unlinked_at" IS 'Date de déliaison ; NULL = liaison active.';
COMMENT ON COLUMN public.discord_links."link_source" IS 'oauth = liée par l''utilisateur ; manual_admin = liée par l''admin.';
COMMENT ON TABLE public.discord_role_grants IS 'Journal des attributions de rôles Discord liés aux formations (une ligne par tentative). Écrit par discord-grant-role, discord-sync et discord-retirer-roles. Rôle actif = status success et revoked_at NULL. Les lignes pending sans Discord lié portent discord_user_id/discord_role_id = PENDING.';
COMMENT ON COLUMN public.discord_role_grants."discord_role_id" IS 'Rôle Discord : 1507701731402973265 = Marketing ; 1507702355024416830 = Setting ; 1507702613225897984 = Closing ; PENDING = rôle pas encore attribué.';
COMMENT ON COLUMN public.discord_role_grants."formation_id" IS 'Formation qui ouvre le rôle (formations.id).';
COMMENT ON COLUMN public.discord_role_grants."granted_at" IS 'Date d''attribution.';
COMMENT ON COLUMN public.discord_role_grants."revoked_at" IS 'Retrait du rôle (ex. accès suspendu : pass retiré ou impayé) ; NULL = actif.';
COMMENT ON COLUMN public.discord_role_grants."reason" IS 'Motif technique de l''attribution (ex. cron_daily_sync, hot_check_at_login).';
COMMENT ON COLUMN public.discord_role_grants."source" IS 'auto = fin de formation ; manual = admin ; sync = cron quotidien ; hot_check = vérification à la connexion ; rejoin = retour sur le serveur.';
COMMENT ON COLUMN public.discord_role_grants."granted_by" IS 'Admin à l''origine (attributions manuelles).';
COMMENT ON COLUMN public.discord_role_grants."status" IS 'success = rôle donné ; failed = échec (voir error_message) ; pending = en attente (Discord non lié ou pas sur le serveur).';
COMMENT ON VIEW public.email_campaign_duplicates IS 'Vue de contrôle : couples (campagne, séquence, adresse) envoyés plus d''une fois, avec l''écart entre le premier et le dernier envoi. Recalculée depuis email_campaign_sends. Sert à mesurer les doublons d''envoi, pas à compter des destinataires.';
COMMENT ON COLUMN public.email_campaign_duplicates."nb_envois" IS 'Nombre d''envois du même e-mail à la même adresse.';
COMMENT ON COLUMN public.email_campaign_duplicates."premier_envoi" IS 'Premier envoi.';
COMMENT ON COLUMN public.email_campaign_duplicates."dernier_envoi" IS 'Dernier envoi.';
COMMENT ON COLUMN public.email_campaign_duplicates."ecart_secondes" IS 'Secondes entre le premier et le dernier envoi.';
COMMENT ON TABLE public.email_campaign_events IS 'Événements Resend (webhook) sur les e-mails de campagne : une ligne par événement. Rattachement à l''envoi par resend_email_id → email_campaign_sends. La fonction webhook qui écrit ici n''est pas versionnée dans le dépôt. Piège : beaucoup d''ouvertures/clics sont des robots (≈36 % en septembre) ; filtrer avec public.evenement_machine(user_agent) comme le rapport de délivrabilité.';
COMMENT ON COLUMN public.email_campaign_events."resend_email_id" IS 'Identifiant du message Resend ; jointure avec email_campaign_sends.resend_email_id.';
COMMENT ON COLUMN public.email_campaign_events."event_type" IS 'email.sent = accepté ; email.delivered = délivré ; email.opened = ouvert ; email.clicked = lien cliqué ; email.bounced = rejeté ; email.complained = plainte spam.';
COMMENT ON COLUMN public.email_campaign_events."occurred_at" IS 'Moment de l''événement selon Resend (timestamptz).';
COMMENT ON COLUMN public.email_campaign_events."payload" IS 'Corps brut du webhook Resend.';
COMMENT ON COLUMN public.email_campaign_events."click_url" IS 'URL cliquée (email.clicked uniquement).';
COMMENT ON COLUMN public.email_campaign_events."user_agent" IS 'Navigateur/robot à l''origine de l''ouverture ou du clic ; sert à écarter les robots (evenement_machine).';
COMMENT ON COLUMN public.email_campaign_events."ip_address" IS 'Adresse IP de l''ouverture ou du clic (donnée personnelle).';
COMMENT ON VIEW public.email_campaign_recipient_status IS 'Vue : une ligne par destinataire, campagne et séquence, avec les dates de livraison, ouverture, clic, rejet, plainte et désabonnement. Recalculée à chaque lecture depuis sends + events. Utilisée par l''écran admin de suivi de campagne. Contient e-mails et prénoms (données personnelles). Définition non versionnée dans le dépôt.';
COMMENT ON COLUMN public.email_campaign_recipient_status."sent_at" IS 'Date d''envoi de l''e-mail.';
COMMENT ON COLUMN public.email_campaign_recipient_status."has_failure" IS 'true si un envoi a échoué pour ce destinataire.';
COMMENT ON COLUMN public.email_campaign_recipient_status."error_message" IS 'Erreur d''envoi éventuelle.';
COMMENT ON COLUMN public.email_campaign_recipient_status."delivered_at" IS 'Première livraison (NULL = jamais délivré).';
COMMENT ON COLUMN public.email_campaign_recipient_status."opened_at" IS 'Première ouverture (robots possiblement inclus).';
COMMENT ON COLUMN public.email_campaign_recipient_status."clicked_at" IS 'Premier clic.';
COMMENT ON COLUMN public.email_campaign_recipient_status."bounced_at" IS 'Rejet de l''adresse.';
COMMENT ON COLUMN public.email_campaign_recipient_status."complained_at" IS 'Plainte spam.';
COMMENT ON COLUMN public.email_campaign_recipient_status."unsubscribed_at" IS 'Désabonnement de l''adresse.';
COMMENT ON TABLE public.email_campaign_recipients IS 'Liste des destinataires prévus d''une campagne e-mail : une ligne par adresse et par campaign_slug. Pour les conférences, remplie par rafraichir_liste_conference (témoins internes d''abord, puis inscrits de la conférence dédoublonnés par e-mail). Ce qui a réellement été envoyé est dans email_campaign_sends ; les désabonnés et exclus sont filtrés au moment de l''envoi, pas ici.';
COMMENT ON COLUMN public.email_campaign_recipients."campaign_slug" IS 'Campagne à laquelle appartient la liste (même code que email_campaign_sends).';
COMMENT ON COLUMN public.email_campaign_recipients."position" IS 'Ordre d''envoi dans la liste (témoins en tête).';
COMMENT ON COLUMN public.email_campaign_recipients."email" IS 'Adresse du destinataire, en minuscules (donnée personnelle).';
COMMENT ON COLUMN public.email_campaign_recipients."first_name" IS 'Prénom utilisé dans l''e-mail (donnée personnelle).';
COMMENT ON TABLE public.email_campaign_sends IS 'Journal des e-mails de campagne envoyés via Resend : une ligne par tentative d''envoi (destinataire × campagne × séquence). Écrit par les edge functions send-*-mail (conférence, albaraka-200, liberty, questionnaire) et send-annonce-eleves. Piège : des doublons existent (relances concurrentes, ex. 353 sur la conférence du 31/05/2026) — dédoublonner par (campaign_slug, email_seq, recipient_email). Les envois de test n''y sont pas écrits.';
COMMENT ON COLUMN public.email_campaign_sends."campaign_slug" IS 'Campagne : conf_AAAA_MM_JJ (séquence d''une conférence), albaraka_200_lancement, tunnel_liberty, annonce_eleves_2026_10, questionnaire_clients…';
COMMENT ON COLUMN public.email_campaign_sends."email_seq" IS 'Numéro de l''e-mail dans la séquence. Conférence depuis le 13/09/2026 : 10 = J-1, 8 = M-30, 9 = ouverture, 11 à 15 = après la conférence.';
COMMENT ON COLUMN public.email_campaign_sends."recipient_email" IS 'Adresse du destinataire (donnée personnelle).';
COMMENT ON COLUMN public.email_campaign_sends."recipient_first_name" IS 'Prénom du destinataire (donnée personnelle).';
COMMENT ON COLUMN public.email_campaign_sends."resend_email_id" IS 'Identifiant du message chez Resend ; clé de jointure avec email_campaign_events.resend_email_id. NULL si l''envoi a échoué.';
COMMENT ON COLUMN public.email_campaign_sends."subject" IS 'Objet de l''e-mail envoyé.';
COMMENT ON COLUMN public.email_campaign_sends."sent_at" IS 'Date et heure de l''envoi (timestamptz).';
COMMENT ON COLUMN public.email_campaign_sends."status" IS 'sent = accepté par Resend ; failed = refusé à l''envoi (voir error_message).';
COMMENT ON COLUMN public.email_campaign_sends."error_message" IS 'Erreur renvoyée par Resend quand status = failed.';
COMMENT ON VIEW public.email_campaign_stats IS 'Vue : statistiques par campagne e-mail et par séquence, recalculées à chaque lecture à partir de email_campaign_sends et email_campaign_events. Lisible par le CEO et les coachs (security_invoker). Définition en base seulement (non versionnée) : le filtrage des robots et le dédoublonnage sont à confirmer ; pour des taux d''ouverture fiables, préférer un calcul avec evenement_machine.';
COMMENT ON COLUMN public.email_campaign_stats."nb_envoyes" IS 'Nombre d''envois (status = sent).';
COMMENT ON COLUMN public.email_campaign_stats."nb_echec_envoi" IS 'Nombre d''envois refusés par Resend (status = failed).';
COMMENT ON COLUMN public.email_campaign_stats."nb_delivres" IS 'Nombre d''e-mails ayant un événement email.delivered.';
COMMENT ON COLUMN public.email_campaign_stats."nb_ouverts" IS 'Nombre d''e-mails ouverts (robots possiblement inclus, à confirmer).';
COMMENT ON COLUMN public.email_campaign_stats."nb_clics" IS 'Nombre d''e-mails cliqués.';
COMMENT ON COLUMN public.email_campaign_stats."nb_bounces" IS 'Nombre d''e-mails rejetés (email.bounced).';
COMMENT ON COLUMN public.email_campaign_stats."nb_complaints" IS 'Nombre de plaintes spam (email.complained).';
COMMENT ON COLUMN public.email_campaign_stats."nb_desabos" IS 'Nombre de désabonnements rattachés (source exacte à confirmer : email_unsubscribes).';
COMMENT ON COLUMN public.email_campaign_stats."premier_envoi_at" IS 'Premier envoi de la séquence.';
COMMENT ON COLUMN public.email_campaign_stats."dernier_envoi_at" IS 'Dernier envoi de la séquence.';
COMMENT ON TABLE public.email_unsubscribe_tokens IS 'Un jeton de désabonnement stable par adresse e-mail, inséré dans les liens des e-mails de campagne. Table technique : pas d''intérêt pour l''analyse (ce n''est pas une liste de désabonnés).';
COMMENT ON COLUMN public.email_unsubscribe_tokens."email" IS 'Adresse concernée (clé primaire).';
COMMENT ON COLUMN public.email_unsubscribe_tokens."token" IS 'Jeton du lien de désabonnement (masquée pour le connecteur).';
COMMENT ON TABLE public.email_unsubscribes IS 'Adresses désabonnées des envois de campagne (une ligne par adresse). Alimentée par l''edge function desabonnement (page /stop ou bouton « se désabonner » de la messagerie). Exclues des envois via emails_a_exclure_conference. Existe depuis le 16/09/2026 : avant, aucun désabonnement n''était possible.';
COMMENT ON COLUMN public.email_unsubscribes."email" IS 'Adresse désabonnée (clé primaire, donnée personnelle).';
COMMENT ON COLUMN public.email_unsubscribes."motif" IS 'Raison donnée par la personne, facultative.';
COMMENT ON COLUMN public.email_unsubscribes."source" IS 'lien = clic sur le lien de désabonnement ; un-clic = désabonnement en un clic depuis la messagerie (List-Unsubscribe).';
COMMENT ON COLUMN public.email_unsubscribes."created_at" IS 'Date du désabonnement.';
COMMENT ON TABLE public.factures_recouvrement IS 'Une ligne = une facture de recouvrement REC0000001… créée pour une échéance impayée transmise au cabinet d''avocats (jamais envoyée au client). Datée du jour de l''échéance ; une par échéance. Si le client paie ensuite, une facture FAC normale s''ajoute et la REC reste. Montant en euros. Données client figées. Lecture CEO.';
COMMENT ON COLUMN public.factures_recouvrement."numero" IS 'Numéro REC + 7 chiffres ; jamais réattribué (suite = plus grand numéro + 1).';
COMMENT ON COLUMN public.factures_recouvrement."payment_id" IS 'Échéance impayée concernée (payments.id), unique.';
COMMENT ON COLUMN public.factures_recouvrement."montant" IS 'Montant réclamé en euros (= montant de l''échéance).';
COMMENT ON COLUMN public.factures_recouvrement."date_facture" IS 'Date de la facture = date d''échéance impayée.';
COMMENT ON COLUMN public.factures_recouvrement."produit" IS 'Libellé du produit.';
COMMENT ON COLUMN public.factures_recouvrement."origine" IS 'plateforme = créée depuis la plateforme ; fichier_cabinet = reprise du fichier déjà transmis au cabinet le 29/08/2026.';
COMMENT ON COLUMN public.factures_recouvrement."transmise_le" IS 'Date de transmission au cabinet (seul champ modifiable).';
COMMENT ON COLUMN public.factures_recouvrement."pdf_path" IS 'Chemin du PDF dans le stockage.';
COMMENT ON TABLE public.fixed_charges IS 'Une ligne = une charge fixe de l''entreprise (abonnement logiciel, frais ponctuel…) saisie par le CEO dans le Dashboard Financier. Montant en euros par occurrence selon la fréquence. Pas de distinction HT/TTC (montant tel que saisi).';
COMMENT ON COLUMN public.fixed_charges."name" IS 'Nom de la charge.';
COMMENT ON COLUMN public.fixed_charges."amount" IS 'Montant en euros par occurrence (par mois, par an ou une fois selon frequency).';
COMMENT ON COLUMN public.fixed_charges."frequency" IS 'monthly = mensuelle ; yearly = annuelle (comptée au mois anniversaire) ; one_time = ponctuelle.';
COMMENT ON COLUMN public.fixed_charges."category" IS 'Catégorie (en pratique toujours ''subscription'').';
COMMENT ON COLUMN public.fixed_charges."is_active" IS 'false = charge arrêtée, ignorée par les calculs.';
COMMENT ON COLUMN public.fixed_charges."start_date" IS 'Début (ou date de la charge ponctuelle).';
COMMENT ON COLUMN public.fixed_charges."end_date" IS 'Fin éventuelle.';
COMMENT ON TABLE public.formation_certificates IS 'Une ligne = un certificat de fin de formation délivré à un élève, par l''edge function issue-certificate (auto quand tous les chapitres publiés sont terminés, ou manuel par le CEO). Exclure revoked_at non null pour les certificats valides. Table créée hors migrations versionnées.';
COMMENT ON COLUMN public.formation_certificates."certificate_number" IS 'Numéro public (format ABT-année-…-numéro), vérifiable sur /verify/<numéro>.';
COMMENT ON COLUMN public.formation_certificates."user_id" IS 'Élève (profiles.id).';
COMMENT ON COLUMN public.formation_certificates."issued_by" IS 'Qui a délivré (profiles.id) ; null pour un certificat automatique.';
COMMENT ON COLUMN public.formation_certificates."issue_source" IS 'auto = délivré à la complétion ; manual = délivré par le CEO.';
COMMENT ON COLUMN public.formation_certificates."pdf_storage_path" IS 'Chemin du PDF dans le stockage.';
COMMENT ON COLUMN public.formation_certificates."revoked_at" IS 'Révocation. Null = certificat valide.';
COMMENT ON TABLE public.formation_chapitres IS 'Une ligne = un chapitre d''un module de formation. Contient les chapitres des formations classiques ET des nouveaux parcours (Setting/Closing, Community Management, Liberty), stockés comme des formations. Ne compter que status = published. Certains chapitres sont des copies reliées à leur origine (parcours_correspondances_chapitres).';
COMMENT ON COLUMN public.formation_chapitres."module_id" IS 'Module (formation_modules.id).';
COMMENT ON COLUMN public.formation_chapitres."status" IS 'draft = brouillon (CEO seul) ; published = visible ; archived = retiré.';
COMMENT ON COLUMN public.formation_chapitres."duree_estimee_minutes" IS 'Durée estimée en minutes.';
COMMENT ON COLUMN public.formation_chapitres."legacy_id" IS 'Ancien identifiant d''avant la migration du contenu (usage à confirmer).';
COMMENT ON COLUMN public.formation_chapitres."notes_formateur" IS 'Encadré « À retenir » du formateur.';
COMMENT ON COLUMN public.formation_chapitres."outil" IS 'Outil ouvert en fin de chapitre (ex. script_appel_setter_closer, liberty_niche_avatar…). Null = aucun.';
COMMENT ON COLUMN public.formation_chapitres."verrou_quiz_id" IS 'Quiz à réussir pour ouvrir ce chapitre, même en navigation libre.';
COMMENT ON COLUMN public.formation_chapitres."sans_video" IS 'Vrai = page sans vidéo (outil, validation, ressources).';
COMMENT ON TABLE public.formation_discord_roles IS 'Rôle Discord donné à l''élève quand il termine une formation (ex. Setting, Closing, Marketing). Une ligne par formation. Utilisé par les fonctions Discord.';
COMMENT ON COLUMN public.formation_discord_roles."discord_role_id" IS 'Identifiant du rôle sur le serveur Discord.';
COMMENT ON COLUMN public.formation_discord_roles."discord_role_label" IS 'Nom du rôle.';
COMMENT ON COLUMN public.formation_discord_roles."channel_ids" IS 'Salons Discord ouverts par ce rôle.';
COMMENT ON TABLE public.formation_enrollments IS 'Une ligne = l''accès d''un élève à une formation. Inscription active = revoked_at IS NULL. Créée par le pass (déclencheurs), le webhook Stripe (achat à la carte), le parcours ou le CEO. Unique (user_id, formation_id). Une inscription n''est pas une progression : voir chapitre_progress.';
COMMENT ON COLUMN public.formation_enrollments."user_id" IS 'Élève (auth.users.id = profiles.id).';
COMMENT ON COLUMN public.formation_enrollments."source" IS 'auto_pass = via un Pass actif ; auto_free = formation libre ; parcours = via l''ancien parcours ; a_la_carte = achat Stripe ; auto_cm_complete = fin du CM ; manual = CEO ; autres = historiques.';
COMMENT ON COLUMN public.formation_enrollments."granted_by" IS 'Qui a donné l''accès (auth.users.id) ; null si automatique.';
COMMENT ON COLUMN public.formation_enrollments."granted_at" IS 'Date d''ouverture de l''accès.';
COMMENT ON COLUMN public.formation_enrollments."revoked_at" IS 'Retrait de l''accès (ex. pass retiré). Null = accès actif.';
COMMENT ON TABLE public.formation_modules IS 'Une ligne = un module d''une formation. Dans les parcours stockés comme formations, un module = une « partie » (Setting/Closing : ordre 1 Setting, 2 Closing ; Community Management : 3 Marketing, 4 CM) ou une étape (Parcours Liberty). Ne compter que status = published.';
COMMENT ON COLUMN public.formation_modules."formation_id" IS 'Formation (formations.id).';
COMMENT ON COLUMN public.formation_modules."ordre" IS 'Position dans la formation ; sert à identifier les parties des parcours.';
COMMENT ON COLUMN public.formation_modules."status" IS 'draft = brouillon ; published = visible ; archived = retiré.';
COMMENT ON COLUMN public.formation_modules."legacy_id" IS 'Ancien identifiant d''avant la migration du contenu (usage à confirmer).';
COMMENT ON COLUMN public.formation_modules."etape" IS 'Titre de groupe affiché au-dessus du module (Parcours Liberty : PARTIE 1 à 5, BONUS). Null = pas de groupe.';
COMMENT ON TABLE public.formations IS 'Catalogue des formations (une dizaine). Inclut les formations classiques et les parcours récents stockés comme formations : parcours-setter-closer, parcours-community-management, parcours-liberty. L''ancien Parcours Al Baraka est dans la table parcours. Les anciennes formations sont masquées aux élèves depuis le 12/10/2026 mais leurs données restent.';
COMMENT ON COLUMN public.formations."slug" IS 'Code stable de la formation (ex. parcours-setter-closer, estimaction). À utiliser dans les filtres plutôt que le titre.';
COMMENT ON COLUMN public.formations."status" IS 'draft = brouillon ; published = en ligne ; archived = retirée.';
COMMENT ON COLUMN public.formations."access_mode" IS 'pass = donnée à tout Pass actif ; liberty_only = Pass Liberty seul ; free = libre ; parcours = débloquée par l''ancien parcours ; al_baraka_only = prévu, inutilisé.';
COMMENT ON COLUMN public.formations."navigation_libre" IS 'Vrai = les quiz ne bloquent pas les chapitres suivants.';
COMMENT ON COLUMN public.formations."masquee_eleves" IS 'Vrai = invisible pour les élèves (CEO seul) ; progression et certificats conservés.';
COMMENT ON COLUMN public.formations."legacy_id" IS 'Ancien identifiant (usage à confirmer).';
COMMENT ON COLUMN public.formations."ordre" IS 'Ordre d''affichage (négatif = en tête).';
COMMENT ON TABLE public.historique_connexions IS 'Historique des connexions à la plateforme : une ligne par ouverture de session, au plus une toutes les 30 minutes par personne. Preuve d''accès exigée par les contrats v3 ; conservé au moins 5 ans. Existe depuis le 13/11/2026 seulement. Lecture CEO.';
COMMENT ON COLUMN public.historique_connexions."user_id" IS 'Utilisateur connecté (users.id = profiles.id).';
COMMENT ON COLUMN public.historique_connexions."connecte_le" IS 'Date et heure de connexion (timestamptz).';
COMMENT ON COLUMN public.historique_connexions."adresse_ip" IS 'Adresse IP (donnée personnelle).';
COMMENT ON COLUMN public.historique_connexions."navigateur" IS 'User-agent du navigateur.';
COMMENT ON TABLE public.ia_consommations IS 'Journal de chaque appel à l''IA (tout passe par OpenRouter depuis le 19/10/2026) : qui, quelle fonctionnalité, modèle, tokens, coût en dollars US. Alimenté par les edge functions (_shared/ia.ts), le Studio (studio_job_cout, fin des tâches de banque), l''analyse d''appels et /api/studio/theme. Source du dashboard /admin/ia (CEO). Avant le 19/10 : seul le Studio a été repris (statut reprise), le reste n''était pas mesuré.';
COMMENT ON COLUMN public.ia_consommations."user_id" IS 'Utilisateur à qui la dépense est imputée (élève, coach…) ; = profiles.id. null = tâche de fond sans personne.';
COMMENT ON COLUMN public.ia_consommations."fonctionnalite" IS 'Code de la fonctionnalité : studio_face_camera (inclut hybride), studio_voix_off, studio_theme, studio_banque, agent_setting, analyse_appels, coach_activite, recap_hebdo…';
COMMENT ON COLUMN public.ia_consommations."modele" IS 'Modèle OpenRouter. Pour les lignes Studio (montages, banque) c''est une étiquette fixe : le coût couvre toutes les IA du montage.';
COMMENT ON COLUMN public.ia_consommations."tokens_entree" IS 'Tokens envoyés ; null pour le Studio et l''analyse d''appels (coût déclaré globalement).';
COMMENT ON COLUMN public.ia_consommations."tokens_sortie" IS 'Tokens générés ; null pour le Studio et l''analyse d''appels.';
COMMENT ON COLUMN public.ia_consommations."cout_usd" IS 'Coût en dollars US (pas en euros), plafonné à 5 $ par ligne. Peut valoir 0 sur une erreur.';
COMMENT ON COLUMN public.ia_consommations."reference" IS 'Origine de la dépense : montage:<id studio_montages>, banque:<id studio_banque_jobs>, appel:<id appels_analyses>:<étape>… ; souvent null ailleurs.';
COMMENT ON COLUMN public.ia_consommations."statut" IS 'ok = appel réussi ; erreur = appel refusé ou montage en panne ; reprise = historique Studio recopié le 19/10/2026 (date = date du montage).';
COMMENT ON COLUMN public.ia_consommations."cree_le" IS 'Date de l''appel IA (UTC ; convertir en Europe/Paris pour les jours).';
COMMENT ON TABLE public.invitation_campaign_runs IS 'Journal des passages du traitement automatique de la campagne d''invitation d''avril 2026 (une ligne par exécution). Historique, sans intérêt pour l''analyse courante.';
COMMENT ON COLUMN public.invitation_campaign_runs."processed" IS 'Personnes traitées lors du passage.';
COMMENT ON COLUMN public.invitation_campaign_runs."sent" IS 'Invitations envoyées.';
COMMENT ON COLUMN public.invitation_campaign_runs."failed" IS 'Invitations en échec.';
COMMENT ON COLUMN public.invitation_campaign_runs."triggered_by" IS 'Déclencheur du passage (cron ou manuel ; valeurs à confirmer).';
COMMENT ON TABLE public.invitation_campaigns IS 'Campagne d''invitation en accès anticipé d''avril 2026 : une ligne par personne invitée, réparties en 3 vagues. Suivie sur la page admin « invitations » (marquée temporaire). Campagne terminée : données historiques. L''envoi automatique n''est pas versionné dans le dépôt.';
COMMENT ON COLUMN public.invitation_campaigns."user_id" IS 'Personne invitée (profiles.id).';
COMMENT ON COLUMN public.invitation_campaigns."wave_number" IS 'Vague d''envoi : 1, 2 ou 3.';
COMMENT ON COLUMN public.invitation_campaigns."planned_date" IS 'Date prévue de l''invitation.';
COMMENT ON COLUMN public.invitation_campaigns."planned_time" IS 'Heure prévue (sans fuseau ; heure de Paris supposée, à confirmer).';
COMMENT ON COLUMN public.invitation_campaigns."sent_at" IS 'Envoi réel ; NULL = pas encore envoyé.';
COMMENT ON COLUMN public.invitation_campaigns."error" IS 'Erreur d''envoi ; NULL = pas d''erreur.';
COMMENT ON TABLE public.invoice_lines IS 'Une ligne = une ligne d''une facture bénéficiaire (apporteur_invoices) : une commission sur une échéance, ou la ligne « Salaire fixe mensuel » (sale_id et payment_id NULL). Montants en euros, figés à la génération. Supprimées avec la facture.';
COMMENT ON COLUMN public.invoice_lines."invoice_id" IS 'Facture bénéficiaire (apporteur_invoices.id).';
COMMENT ON COLUMN public.invoice_lines."payment_id" IS 'Échéance client commissionnée (payments.id) ; NULL pour le salaire fixe.';
COMMENT ON COLUMN public.invoice_lines."sale_id" IS 'Vente (sales.id) ; NULL pour le salaire fixe.';
COMMENT ON COLUMN public.invoice_lines."client_name" IS 'Nom du client figé (ou « Salaire fixe mensuel »).';
COMMENT ON COLUMN public.invoice_lines."payment_date" IS 'Date d''encaissement de l''échéance client.';
COMMENT ON COLUMN public.invoice_lines."payment_amount" IS 'Montant de l''échéance client en euros (0 pour le salaire fixe).';
COMMENT ON COLUMN public.invoice_lines."commission_percentage" IS 'Taux en % (0 pour le salaire fixe).';
COMMENT ON COLUMN public.invoice_lines."commission_amount" IS 'Montant facturé en euros (commission ou salaire fixe).';
COMMENT ON TABLE public.lead_activities IS 'Historique d''une fiche lead (une ligne par action), ajout seul : changements de statut, affectations, notes, relances, recyclages. Écrit par l''appli et les fonctions en base ; les actions automatiques portent le CEO ou le setter en user_id. Base des stats d''équipe (appels, qualifications par setter).';
COMMENT ON COLUMN public.lead_activities."lead_id" IS 'Fiche concernée (leads.id).';
COMMENT ON COLUMN public.lead_activities."user_id" IS 'Auteur (profiles.id) ; pour une action automatique, le setter en charge ou le CEO.';
COMMENT ON COLUMN public.lead_activities."action" IS 'status_change ; assigned, reassigned, unassigned ; created ; note_added ; relance_faite ; recycled ; dm_bascule ; rappel_demande ; follow_up_reporte ; suivi_closer ; questionnaire_saisi ; tag_*';
COMMENT ON COLUMN public.lead_activities."old_value" IS 'Valeur avant (statut, setter, étape de relance…).';
COMMENT ON COLUMN public.lead_activities."new_value" IS 'Valeur après (statut, setter, étape suivante, priorité…).';
COMMENT ON COLUMN public.lead_activities."note" IS 'Note ou explication de l''action.';
COMMENT ON TABLE public.lead_canaux IS 'Liste des canaux d''acquisition (d''où vient le trafic) gérés par le CEO dans « Gérer les sources » : renommer, désactiver, créer, fusionner. Le canal d''un lead est CALCULÉ (lead_attribution), jamais stocké. Un canal créé ici est utilisable dans un lien ?src=<clé>.';
COMMENT ON COLUMN public.lead_canaux."cle" IS 'Code du canal (ex. meta_ads, snap_ads, google_ads, instagram, youtube, site_vitrine, apporteur, sans_source, autre, ou canal créé).';
COMMENT ON COLUMN public.lead_canaux."libelle" IS 'Nom affiché.';
COMMENT ON COLUMN public.lead_canaux."groupe" IS 'ads = publicité payante ; organique ; apporteur ; autre. Sert à dire si un lead vient de la pub.';
COMMENT ON COLUMN public.lead_canaux."couleur" IS 'Couleur du badge à l''écran.';
COMMENT ON COLUMN public.lead_canaux."actif" IS 'Faux = canal désactivé (ses leads gardent ce canal).';
COMMENT ON COLUMN public.lead_canaux."ordre" IS 'Ordre d''affichage.';
COMMENT ON COLUMN public.lead_canaux."systeme" IS 'Vrai pour sans_source et autre : ni supprimables ni fusionnables.';
COMMENT ON COLUMN public.lead_canaux."desactive_le" IS 'Date de désactivation.';
COMMENT ON TABLE public.lead_canaux_alias IS 'Après fusion de deux canaux : l''ancienne clé pointe vers le canal gardé (aussi pour les anciens liens ?src=). Lu par lead_attribution.';
COMMENT ON COLUMN public.lead_canaux_alias."ancien" IS 'Ancienne clé de canal (ou jeton ?src=).';
COMMENT ON COLUMN public.lead_canaux_alias."canal" IS 'Canal gardé (lead_canaux.cle).';
COMMENT ON TABLE public.lead_quiz_configs IS 'Versions du contenu du quiz apporteur (questions, profils, page d''accueil, message WhatsApp), éditées dans l''admin du quiz. Une seule version active ; une modification crée une nouvelle version.';
COMMENT ON COLUMN public.lead_quiz_configs."version" IS 'Numéro de version (recopié dans lead_quiz_submissions.config_version).';
COMMENT ON COLUMN public.lead_quiz_configs."questions" IS 'Questions et réponses du quiz (JSON).';
COMMENT ON COLUMN public.lead_quiz_configs."profiles" IS 'Profils de résultat (batisseur, connecteur, createur) et leurs textes (JSON).';
COMMENT ON COLUMN public.lead_quiz_configs."orientation_question" IS 'Question d''orientation finale (JSON).';
COMMENT ON COLUMN public.lead_quiz_configs."landing" IS 'Textes de la page d''accueil (JSON).';
COMMENT ON COLUMN public.lead_quiz_configs."intro" IS 'Textes d''introduction (JSON).';
COMMENT ON COLUMN public.lead_quiz_configs."conference" IS 'Textes sur la conférence (JSON).';
COMMENT ON COLUMN public.lead_quiz_configs."whatsapp_message" IS 'Message pré-rempli envoyé à l''apporteur sur WhatsApp.';
COMMENT ON COLUMN public.lead_quiz_configs."is_active" IS 'Vrai = version en ligne.';
COMMENT ON TABLE public.lead_quiz_owners IS 'Page de quiz personnelle d''un apporteur ou élève (/q/<slug>) servant à générer des leads : une ligne par propriétaire. Les leads issus ont source apporteur_quiz et apporteur_id = user_id.';
COMMENT ON COLUMN public.lead_quiz_owners."user_id" IS 'Propriétaire de la page (profiles.id), crédité comme apporteur.';
COMMENT ON COLUMN public.lead_quiz_owners."slug" IS 'Identifiant dans l''URL de la page ; repris dans leads.source_detail (quiz:<slug>).';
COMMENT ON COLUMN public.lead_quiz_owners."display_name" IS 'Nom affiché sur la page.';
COMMENT ON COLUMN public.lead_quiz_owners."display_role" IS 'Rôle affiché (COACH AL BARAKA, Membre AL BARAKA…).';
COMMENT ON COLUMN public.lead_quiz_owners."whatsapp_phone" IS 'Numéro WhatsApp du propriétaire, vers lequel le prospect est renvoyé.';
COMMENT ON COLUMN public.lead_quiz_owners."is_active" IS 'Faux = page désactivée.';
COMMENT ON COLUMN public.lead_quiz_owners."total_views" IS 'Compteur cumulé de visites de la page (sans suivi individuel).';
COMMENT ON TABLE public.lead_quiz_submissions IS 'Un passage d''un prospect dans le quiz apporteur (une ligne par prospect et par page). Créée avec le lead CRM dès la saisie des coordonnées (téléphone obligatoire depuis le 14/05/2026), puis mise à jour à chaque étape. Écrit par submit-quiz-lead.';
COMMENT ON COLUMN public.lead_quiz_submissions."owner_id" IS 'Page de quiz (lead_quiz_owners.id).';
COMMENT ON COLUMN public.lead_quiz_submissions."config_version" IS 'Version du quiz utilisée (lead_quiz_configs.version).';
COMMENT ON COLUMN public.lead_quiz_submissions."first_name" IS 'Prénom. Donnée personnelle.';
COMMENT ON COLUMN public.lead_quiz_submissions."last_name" IS 'Nom. Donnée personnelle.';
COMMENT ON COLUMN public.lead_quiz_submissions."email" IS 'E-mail. Donnée personnelle.';
COMMENT ON COLUMN public.lead_quiz_submissions."phone" IS 'Téléphone. Donnée personnelle.';
COMMENT ON COLUMN public.lead_quiz_submissions."status" IS 'Étape atteinte. Ordre actuel : phone_captured (coordonnées, lead créé) → quiz_in_progress → quiz_completed → whatsapp_clicked. email_captured = ancien flux.';
COMMENT ON COLUMN public.lead_quiz_submissions."last_question_reached" IS 'Dernière question atteinte.';
COMMENT ON COLUMN public.lead_quiz_submissions."answers" IS 'Réponses du quiz (JSON).';
COMMENT ON COLUMN public.lead_quiz_submissions."profile" IS 'Profil obtenu : batisseur, connecteur ou createur.';
COMMENT ON COLUMN public.lead_quiz_submissions."scores" IS 'Scores par profil (JSON).';
COMMENT ON COLUMN public.lead_quiz_submissions."orientation_choice" IS 'Réponse à la question d''orientation finale.';
COMMENT ON COLUMN public.lead_quiz_submissions."whatsapp_clicked_at" IS 'Clic final vers le WhatsApp du propriétaire.';
COMMENT ON COLUMN public.lead_quiz_submissions."last_seen_at" IS 'Dernière activité du prospect.';
COMMENT ON COLUMN public.lead_quiz_submissions."referrer" IS 'Page de provenance.';
COMMENT ON COLUMN public.lead_quiz_submissions."ip_country" IS 'Pays d''après l''adresse IP.';
COMMENT ON COLUMN public.lead_quiz_submissions."contact_id" IS 'Contact (contacts.id).';
COMMENT ON COLUMN public.lead_quiz_submissions."lead_id" IS 'Fiche lead créée (leads.id).';
COMMENT ON TABLE public.lead_scoring_responses IS 'Un questionnaire de lead scoring rempli (7 questions) : par le prospect après inscription (submit-scoring-quiz) ou saisi par le setter au téléphone. Une personne peut en avoir plusieurs ; leads_enriched_base retient le plus récent (par lead_id ou e-mail). Score /100 et priorité A-D calculés par trigger ; le score /70 est l''ancien.';
COMMENT ON COLUMN public.lead_scoring_responses."funnel_slug" IS 'Questionnaire d''origine (quiz_funnel_configs.slug) ; saisie-setter = saisi par le setter.';
COMMENT ON COLUMN public.lead_scoring_responses."pending_token_id" IS 'Jeton de rattachement utilisé (pending_scoring_tokens.id).';
COMMENT ON COLUMN public.lead_scoring_responses."contact_email" IS 'E-mail du répondant. Donnée personnelle.';
COMMENT ON COLUMN public.lead_scoring_responses."answers" IS 'Réponses q1..q7 (codes, ex. q1=salarie, q4=500_1000).';
COMMENT ON COLUMN public.lead_scoring_responses."score" IS 'Ancien score /70, gardé en lecture seule pour comparaison (à partir du 28/10/2026).';
COMMENT ON COLUMN public.lead_scoring_responses."category" IS 'Ancienne catégorie /70 : chaud (≥56), tiede (≥39), froid (≥21), hors_cible.';
COMMENT ON COLUMN public.lead_scoring_responses."flags" IS 'Signaux : age_hors_cible, appel_prioritaire, desalignement_humain, investissement_faible.';
COMMENT ON COLUMN public.lead_scoring_responses."client_ip" IS 'IP du répondant.';
COMMENT ON COLUMN public.lead_scoring_responses."completed_at" IS 'Date de fin du questionnaire.';
COMMENT ON COLUMN public.lead_scoring_responses."score_100" IS 'Score /100 calculé par scoring_calcul avec la grille grille_version. NULL si une réponse manque.';
COMMENT ON COLUMN public.lead_scoring_responses."priorite" IS 'Priorité d''appel : A ≥ seuil_a, B ≥ seuil_b, C ≥ seuil_c, sinon D (seuils de la grille).';
COMMENT ON COLUMN public.lead_scoring_responses."grille_version" IS 'Grille utilisée (scoring_grilles.version) ; l''historique est recalculé à chaque nouvelle grille.';
COMMENT ON COLUMN public.lead_scoring_responses."lead_id" IS 'Fiche lead (leads.id) ; surtout rempli pour les saisies setter.';
COMMENT ON COLUMN public.lead_scoring_responses."saisi_par" IS 'Setter qui a saisi les réponses au téléphone. Ces lignes donnent une priorité mais restent hors du recalage de la grille.';
COMMENT ON TABLE public.lead_sources_map IS 'Traduit chaque code leads.source en canal + tunnel (+ précision). Lu par lead_attribution ; ne réécrit aucun lead. Un code absent donne le canal sans_source.';
COMMENT ON COLUMN public.lead_sources_map."source" IS 'Code leads.source.';
COMMENT ON COLUMN public.lead_sources_map."canal" IS 'Canal par défaut (lead_canaux.cle). sans_source : le jeton ?src= ou des règles (Snapchat, pub Meta) peuvent le remplacer.';
COMMENT ON COLUMN public.lead_sources_map."tunnel" IS 'Tunnel (lead_tunnels.cle).';
COMMENT ON COLUMN public.lead_sources_map."canal_precision" IS 'Précision fixe (plateforme de l''apporteur, VSL A/B…).';
COMMENT ON TABLE public.lead_tags IS 'Étiquettes de qualification posées par le setter dans la fenêtre du lead (une ligne par étiquette). Catalogue dans le code (src/lib/leadTags.ts) ; utilisé pour la synthèse marketing.';
COMMENT ON COLUMN public.lead_tags."lead_id" IS 'Fiche (leads.id).';
COMMENT ON COLUMN public.lead_tags."tag_key" IS 'Code de l''étiquette, ex. salarie, sans_emploi, etudiant, zero_budget, budget_a_venir, budget_qualifie, pas_de_temps, trop_mefiant.';
COMMENT ON COLUMN public.lead_tags."tag_category" IS 'profil (plusieurs possibles) ; budget (une seule par lead) ; autre.';
COMMENT ON COLUMN public.lead_tags."created_by" IS 'Setter qui a posé l''étiquette.';
COMMENT ON TABLE public.lead_tunnels IS 'Liste des tunnels (page sur laquelle le lead s''est inscrit) : whatsapp (conférence), vsl, liberty, quiz_apporteur, site_vitrine, saisie_manuelle, ancien_webinaire et anciennes_vsl (Systeme.io, inactifs).';
COMMENT ON COLUMN public.lead_tunnels."cle" IS 'Code du tunnel.';
COMMENT ON COLUMN public.lead_tunnels."libelle" IS 'Nom affiché.';
COMMENT ON COLUMN public.lead_tunnels."actif" IS 'Faux = tunnel ancien, plus alimenté.';
COMMENT ON COLUMN public.lead_tunnels."ordre" IS 'Ordre d''affichage.';
COMMENT ON TABLE public.leads IS 'Une fiche lead = une inscription d''une personne par une source (tunnel, quiz, site, Calendly, saisie). Une personne peut avoir plusieurs fiches : dédoublonner par contact_id (ou garder fiche_principale_id IS NULL). Canal et tunnel ne sont pas stockés : les lire dans leads_enriched_base. Une seule fiche par (contact, source, jour UTC) depuis le 09/09/2026. Aucune suppression logique.';
COMMENT ON COLUMN public.leads."contact_id" IS 'Personne (contacts.id). Clé pour relier calls, ventes et autres fiches de la même personne.';
COMMENT ON COLUMN public.leads."source" IS 'Code d''origine (tunnel + trafic) : webi_wa_*, webi_vsl_*, liberty_*, apporteur_*, site_vitrine ; webi, vsl_a, vsl_b = anciens Systeme.io. Traduit en canal/tunnel par lead_sources_map.';
COMMENT ON COLUMN public.leads."source_detail" IS 'Précision brute : jeton ?src= des tunnels (ads, ig, tiktok, youtube, direct ou clé d''un canal créé), quiz:<slug> pour le quiz apporteur.';
COMMENT ON COLUMN public.leads."apporteur_id" IS 'Apporteur qui a apporté le lead (profiles.id) ; base de sa commission. Reste même si le lead change de setter.';
COMMENT ON COLUMN public.leads."assigned_to" IS 'Setter en charge (profiles.id). NULL = au pot (« À affecter » ou « À recycler »).';
COMMENT ON COLUMN public.leads."assigned_at" IS 'Date de la dernière affectation.';
COMMENT ON COLUMN public.leads."status" IS 'a_qualifier = à appeler ; inscrit_conference ; envoi_rediffusion ; call_booke = RDV pris ; renvoi_pole_vente ; close = vendu ; pas_qualifie ; faux_numero ; perdu. Suite : leads_enriched_base.status.';
COMMENT ON COLUMN public.leads."systeme_io_id" IS 'Identifiant du contact chez Systeme.io (anciens leads avant les tunnels natifs).';
COMMENT ON COLUMN public.leads."raw_full_name" IS 'Nom saisi à l''inscription (MAJUSCULES). Donnée personnelle.';
COMMENT ON COLUMN public.leads."raw_email" IS 'E-mail saisi à l''inscription. Donnée personnelle.';
COMMENT ON COLUMN public.leads."raw_phone" IS 'Téléphone saisi, normalisé E.164 par trigger. Sert au repérage « hors zone ». Donnée personnelle.';
COMMENT ON COLUMN public.leads."notes" IS 'Notes libres (src, fbclid, référent, fusions de doublons, notes de l''équipe).';
COMMENT ON COLUMN public.leads."call_type" IS 'Type d''appel saisi à la création manuelle : call_vsl, call_conference, pole_vente. Rarement rempli.';
COMMENT ON COLUMN public.leads."apporteur_source" IS 'Plateforme d''où l''apporteur tient le lead : facebook, whatsapp, instagram, linkedin, recommandation, telegram, tiktok, quiz, autre.';
COMMENT ON COLUMN public.leads."apporteur_source_detail" IS 'Précision libre de l''apporteur (slug du quiz pour apporteur_quiz).';
COMMENT ON COLUMN public.leads."utm_source" IS 'UTM source de la pub (Meta : fb, ig, an = Audience Network, msg = Messenger, th = Threads ; snapchat…).';
COMMENT ON COLUMN public.leads."utm_content" IS 'UTM content : identifiant de la pub (ads_pubs), sert à l''attribution par créa.';
COMMENT ON COLUMN public.leads."recycled_at" IS 'Date de passage au pot « À recycler » (désaffecté). Remis à NULL quand le lead est réattribué.';
COMMENT ON COLUMN public.leads."conference_date" IS 'Conférence (dimanche) suivant l''inscription, posée par trigger à la création (bascule à l''heure de début). Clé du suivi par conférence.';
COMMENT ON COLUMN public.leads."auto_released_at" IS 'Date où un lead apporté encore « à qualifier » a été remis au pot (lundi suivant sa semaine d''inscription). apporteur_id est conservé.';
COMMENT ON COLUMN public.leads."tunnel_variant" IS 'Variante de LANDING vue par l''inscrit (tests etape=''landing''). Nulle sinon.';
COMMENT ON COLUMN public.leads."ab_test_code" IS 'Code du test A/B en cours lors de la visite (ab_tests.code), s''il y en avait un.';
COMMENT ON COLUMN public.leads."visitor_id" IS 'Identifiant anonyme du navigateur, pour rattacher l''inscrit à son exposition A/B (ab_exposures.visitor_id).';
COMMENT ON COLUMN public.leads."jour_creation" IS 'Jour UTC de création, dérivé de created_at. Sert uniquement à la contrainte anti-doublon.';
COMMENT ON COLUMN public.leads."fiche_principale_id" IS 'Fiche principale de la même personne quand plusieurs fiches la décrivent. NULL = fiche autonome ou principale. Rempli sur une partie seulement des doublons.';
COMMENT ON COLUMN public.leads."relance_etape" IS 'Étape de relance d''une fiche a_relancer : 1 à 3 au 1er passage, 4 à 6 au 2e. NULL hors a_relancer. N''avance que par marquer_relance_faite.';
COMMENT ON COLUMN public.leads."relance_derniere_le" IS 'Date de la dernière relance faite (process en cours).';
COMMENT ON COLUMN public.leads."relance_passage_fait" IS 'Vrai si le lead a déjà été recyclé après 3 relances sans réponse : ses relances reprennent à la Relance 4 ; après la 6e il passe perdu.';
COMMENT ON COLUMN public.leads."premiere_action_le" IS 'Première action de l''équipe (statut, note, relance). Délai de traitement = premiere_action_le - created_at.';
COMMENT ON COLUMN public.leads."clic_pub" IS 'JSON d''attribution pub : fbclid, fbc, fbp, meta_adid (Meta), sccid, scid (Snap), gclid (Google), user_agent, event_id, diag ; snap_capi = {http, le} résultat de l''envoi à l''API de conversion Snap.';
COMMENT ON COLUMN public.leads."app_origine" IS 'Appli dont le navigateur a servi à l''inscription (snapchat, instagram, facebook, tiktok, whatsapp, navigateur), d''après le user-agent.';
COMMENT ON COLUMN public.leads."dm_depuis" IS 'Entrée dans Lead Setting DM (relance par message d''un lead de pub perdu). NULL = jamais passé en DM.';
COMMENT ON COLUMN public.leads."dm_perdu_par" IS 'Setter qui avait perdu le lead avant son passage en DM (profiles.id).';
COMMENT ON COLUMN public.leads."dm_contact_reussi_par" IS 'Setter DM qui a obtenu le contact (Inscrit conférence, call…) : touche 5 % sur la vente.';
COMMENT ON COLUMN public.leads."dm_contact_reussi_le" IS 'Date où le Setter DM a obtenu le contact.';
COMMENT ON COLUMN public.leads."follow_up_le" IS 'Date de rappel d''un lead en status follow_up (obligatoire dans ce statut, vidée sinon).';
COMMENT ON COLUMN public.leads."follow_up_motif" IS 'Motif du follow-up (liste ou texte libre), ex. paiement en fin de mois.';
COMMENT ON VIEW public.leads_enriched IS 'Vue : leads_enriched_base filtrée selon le rôle de l''utilisateur connecté (règles de lecture de la table leads). Hors session applicative elle peut renvoyer 0 ligne : pour l''analyse, utiliser leads_enriched_base (mêmes colonnes).';
COMMENT ON VIEW public.leads_enriched_base IS 'Vue d''analyse des leads (une ligne par fiche) : colonnes de leads + contact, noms du setter et de l''apporteur, canal/tunnel/précision calculés (lead_attribution), dernier questionnaire de scoring, prochain call et dernier call du contact, tags Réinscrit et Jeu-Ven. Sans filtre de droits. Recalculée à chaque lecture (~0,4 s).';
COMMENT ON COLUMN public.leads_enriched_base."status" IS 'Autres statuts : a_relancer (relances 1-6) ; rappel_demande ; follow_up (date) ; pas_de_reponse(_post_conference) = recyclé ; dm_a_contacter, contact_dm1, relance_dm1/2, perdu_definitif = DM.';
COMMENT ON COLUMN public.leads_enriched_base."contact_email" IS 'E-mail du contact.';
COMMENT ON COLUMN public.leads_enriched_base."contact_phone" IS 'Téléphone normalisé du contact.';
COMMENT ON COLUMN public.leads_enriched_base."contact_full_name" IS 'Nom du contact.';
COMMENT ON COLUMN public.leads_enriched_base."apporteur_name" IS 'Nom de l''apporteur.';
COMMENT ON COLUMN public.leads_enriched_base."assigned_to_name" IS 'Nom du setter en charge.';
COMMENT ON COLUMN public.leads_enriched_base."contact_call_id" IS 'Prochain call planifié et à venir du contact (status planifie, scheduled_at > maintenant).';
COMMENT ON COLUMN public.leads_enriched_base."contact_call_scheduled_at" IS 'Date de ce prochain call.';
COMMENT ON COLUMN public.leads_enriched_base."contact_call_status" IS 'Statut de ce prochain call (toujours planifie).';
COMMENT ON COLUMN public.leads_enriched_base."contact_call_event_type" IS 'Agenda de ce prochain call.';
COMMENT ON COLUMN public.leads_enriched_base."contact_call_assigned_to" IS 'Closer de ce prochain call.';
COMMENT ON COLUMN public.leads_enriched_base."contact_call_assigned_to_name" IS 'Nom du closer de ce prochain call.';
COMMENT ON COLUMN public.leads_enriched_base."has_active_call" IS 'Vrai si le contact a un call planifié à venir.';
COMMENT ON COLUMN public.leads_enriched_base."source_label" IS 'Ancien libellé de source_detail (VSL A, VSL B…) ; reprend la valeur brute sinon.';
COMMENT ON COLUMN public.leads_enriched_base."status_label" IS 'Libellé du statut, partiel : beaucoup de statuts récents restent en code brut.';
COMMENT ON COLUMN public.leads_enriched_base."quiz_score" IS 'Ancien score /70 du questionnaire (lecture seule).';
COMMENT ON COLUMN public.leads_enriched_base."quiz_category" IS 'Ancienne catégorie /70 : chaud (≥56), tiede (≥39), froid (≥21), hors_cible.';
COMMENT ON COLUMN public.leads_enriched_base."quiz_flags" IS 'Signaux du questionnaire (ex. age_hors_cible, appel_prioritaire, investissement_faible).';
COMMENT ON COLUMN public.leads_enriched_base."quiz_completed_at" IS 'Date du questionnaire retenu (le plus récent, par lead_id ou e-mail du contact).';
COMMENT ON COLUMN public.leads_enriched_base."quiz_answers" IS 'Réponses du questionnaire retenu (JSON q1..q7).';
COMMENT ON COLUMN public.leads_enriched_base."quiz_filled" IS 'Vrai si un questionnaire de scoring est trouvé.';
COMMENT ON COLUMN public.leads_enriched_base."any_call_id" IS 'Dernier call du contact, quel que soit son statut.';
COMMENT ON COLUMN public.leads_enriched_base."any_call_scheduled_at" IS 'Date de ce dernier call.';
COMMENT ON COLUMN public.leads_enriched_base."any_call_status" IS 'Statut de ce dernier call.';
COMMENT ON COLUMN public.leads_enriched_base."has_any_call" IS 'Vrai si le contact a au moins un call.';
COMMENT ON COLUMN public.leads_enriched_base."canal" IS 'Canal calculé (lead_canaux.cle) : meta_ads, snap_ads, google_ads, instagram, youtube, site_vitrine, apporteur, sans_source, autre… Voir glossaire.';
COMMENT ON COLUMN public.leads_enriched_base."tunnel" IS 'Tunnel calculé (lead_tunnels.cle) : whatsapp, vsl, liberty, quiz_apporteur, site_vitrine, saisie_manuelle, anciens tunnels.';
COMMENT ON COLUMN public.leads_enriched_base."canal_precision" IS 'Précision : Instagram/Facebook pour Meta (utm_source), plateforme de l''apporteur, « Sans paramètres » (lien nu ouvert dans Snapchat ou avec pub Meta retrouvée).';
COMMENT ON COLUMN public.leads_enriched_base."quiz_score_100" IS 'Score /100 du questionnaire (grille scoring_grilles).';
COMMENT ON COLUMN public.leads_enriched_base."quiz_priorite" IS 'Priorité d''appel A, B, C ou D tirée du score /100.';
COMMENT ON COLUMN public.leads_enriched_base."quiz_grille_version" IS 'Version de grille utilisée (scoring_grilles.version).';
COMMENT ON COLUMN public.leads_enriched_base."quiz_saisi_par" IS 'Setter qui a saisi le questionnaire au téléphone ; NULL = rempli par le prospect.';
COMMENT ON COLUMN public.leads_enriched_base."reinscrit_de" IS 'Fiche précédente du même contact créée dans les 30 jours, un autre jour (tag « Réinscrit »).';
COMMENT ON COLUMN public.leads_enriched_base."signal_jeu_ven" IS 'Vrai si l''inscription a eu lieu un des jours de scoring_reglages.jours_jeu_ven (jeudi/vendredi par défaut, heure de Paris).';
COMMENT ON COLUMN public.leads_enriched_base."dm_perdu_par_name" IS 'Nom du setter qui avait perdu le lead avant DM.';
COMMENT ON COLUMN public.leads_enriched_base."contact_deja_perdu_dm" IS 'Vrai si une autre fiche du même contact est perdu_definitif.';
COMMENT ON TABLE public.leads_phone_backup_20260418 IS 'Sauvegarde/Obsolète — ne pas utiliser pour l''analyse. Copie des téléphones de leads (raw_phone) avant la normalisation E.164 du 18/04/2026.';
COMMENT ON COLUMN public.leads_phone_backup_20260418."raw_phone" IS 'Valeur avant normalisation.';
COMMENT ON COLUMN public.leads_phone_backup_20260418."backup_at" IS 'Date de la sauvegarde.';
COMMENT ON TABLE public.liberty_modeles IS 'Modèles Word/PowerPoint (contrat, slides VSL, webinaire…) que les outils du Parcours Liberty remplissent pour l''élève. Contenu chargé hors dépôt. Aucune donnée élève ; inutile pour l''analyse.';
COMMENT ON COLUMN public.liberty_modeles."code" IS 'Code du modèle.';
COMMENT ON COLUMN public.liberty_modeles."format" IS 'docx ou pptx.';
COMMENT ON COLUMN public.liberty_modeles."contenu_base64" IS 'Fichier encodé en base64 (volumineux, ne pas sélectionner).';
COMMENT ON TABLE public.liberty_module_progress IS 'Ancien Parcours Liberty (modules M1 à M20, masqué aux élèves depuis le 04/11/2026) : état sauvegardé d''un module-outil par élève. Une ligne par (user_id, module_id). Remplacé par liberty_profil pour le nouveau parcours.';
COMMENT ON COLUMN public.liberty_module_progress."module_id" IS 'Module de l''ancien parcours, code m1 à m20 (texte, pas une clé étrangère).';
COMMENT ON COLUMN public.liberty_module_progress."data" IS 'État des écrans du module (JSON propre à chaque module).';
COMMENT ON COLUMN public.liberty_module_progress."status" IS 'in_progress = commencé ; completed = terminé (voir completed_at).';
COMMENT ON TABLE public.liberty_profil IS 'Nouveau Parcours Liberty : profil unique de l''élève partagé par les 11 outils (avatar, promesse, offre…). Une ligne par élève, chaque information sous une clé du JSON. Écrit champ par champ (fonction liberty_profil_ecrire).';
COMMENT ON COLUMN public.liberty_profil."donnees" IS 'JSON clé → valeur (ex. « avatar.peur », « promesse.delai ») rempli par l''élève dans les outils.';
COMMENT ON TABLE public.liberty_user_profile IS 'Ancien Parcours Liberty : profil partagé des anciens outils M1 à M18, une ligne par élève. Toujours lu par certains écrans et par les scripts d''appel. Distinct de liberty_profil (nouveau parcours).';
COMMENT ON COLUMN public.liberty_user_profile."data" IS 'JSON des réponses de l''élève dans les anciens modules Liberty.';
COMMENT ON TABLE public.marketing_objectifs IS 'Une ligne = l''objectif d''un KPI marketing pour un mois (unique par mois et KPI), saisi par le CEO ou l''agence dans l''onglet Marketing. Un objectif effacé est supprimé (pas de zéro).';
COMMENT ON COLUMN public.marketing_objectifs."mois" IS '1er jour du mois visé.';
COMMENT ON COLUMN public.marketing_objectifs."kpi" IS 'leads = nb de leads ; cpl = coût par lead (€) ; ventes = nb de ventes ; ca = CA HT (€) ; cout_par_vente = dépense pub / ventes (€) ; budget = dépense pub (€) ; roi = (CA − dépense) / dépense, en %.';
COMMENT ON COLUMN public.marketing_objectifs."valeur" IS 'Valeur visée dans l''unité du KPI (€, nombre, ou % pour roi).';
COMMENT ON COLUMN public.marketing_objectifs."updated_by" IS 'Dernier auteur (profiles.id).';
COMMENT ON VIEW public.marketing_ventes_attribuees IS 'Vue : une ligne par vente hors Studio (inclut bon_commande, custom_link, acompte, NULL) avec le lead auquel elle est attribuée pour le marketing. Recalculée à chaque lecture. Joindre lead_id à leads_enriched pour canal/tunnel/pub. Exclure les acomptes pour compter les ventes ; amount_ht en euros (TVA 0 %).';
COMMENT ON COLUMN public.marketing_ventes_attribuees."vente_id" IS 'Vente (sales.id).';
COMMENT ON COLUMN public.marketing_ventes_attribuees."amount_ht" IS 'Montant de la vente en euros (sales.amount_ht).';
COMMENT ON COLUMN public.marketing_ventes_attribuees."lead_id" IS 'Lead attribué : lead de la vente, sinon du call, sinon lead_origine_id, sinon dernier lead du contact créé avant la vente.';
COMMENT ON COLUMN public.marketing_ventes_attribuees."mode_attribution" IS 'direct = lead de la vente ; via_appel = lead du call ; deduit = lead d''origine ou dernier lead du contact ; non_attribue = aucun lead.';
COMMENT ON TABLE public.notifications IS 'Notifications de la cloche de l''application : une ligne par notification et par destinataire. Créées par des triggers, crons et fonctions en base. Une même annonce produit une ligne par destinataire.';
COMMENT ON COLUMN public.notifications."user_id" IS 'Destinataire (profiles.id).';
COMMENT ON COLUMN public.notifications."type" IS 'announcement = annonce CEO ; activity_reminder = rappel d''activité ; follow_up_jour = lead à relancer ce jour ; suivi_closer = lead suivi par un closer ; call_confie = call confié…';
COMMENT ON COLUMN public.notifications."title" IS 'Titre affiché.';
COMMENT ON COLUMN public.notifications."body" IS 'Texte affiché.';
COMMENT ON COLUMN public.notifications."link" IS 'Lien interne ouvert au clic.';
COMMENT ON COLUMN public.notifications."metadata" IS 'Références en JSON (lead_id, announcement_id, appel_id…).';
COMMENT ON COLUMN public.notifications."read_at" IS 'Lecture ; NULL = non lue.';
COMMENT ON TABLE public.objection_categories IS 'Catégories d''objections de la page Scripts (/working/scripts), séparées setting/closing. Contenu éditorial géré par le CEO. Table créée hors migrations versionnées.';
COMMENT ON COLUMN public.objection_categories."icon" IS 'Icône affichée.';
COMMENT ON COLUMN public.objection_categories."type" IS 'setting = objections en prise de RDV ; closing = objections en appel de vente.';
COMMENT ON COLUMN public.objection_categories."status" IS 'published = visible ; draft = brouillon ; archived = retirée.';
COMMENT ON TABLE public.objections IS 'Une ligne = une objection type et la réponse conseillée, dans une catégorie (objection_categories). Affichée dans Scripts et utilisée comme base de connaissance par l''agent IA prospect (claude-agent-prospect). Contenu éditorial.';
COMMENT ON COLUMN public.objections."category_id" IS 'Catégorie (objection_categories.id).';
COMMENT ON COLUMN public.objections."situation" IS 'Objection du prospect.';
COMMENT ON COLUMN public.objections."reponse" IS 'Réponse conseillée.';
COMMENT ON COLUMN public.objections."verbatim" IS 'Formulation mot pour mot à dire (facultative).';
COMMENT ON COLUMN public.objections."etapes" IS 'Étapes de traitement de l''objection (liste de textes).';
COMMENT ON TABLE public.offers IS 'Catalogue des offres officielles : Pass AL BARAKA, Pass Liberty, Al Baraka 200 €/mois, formations à la carte. Prix de référence et fourchette d''échéances, lus par le checkout et les liens de paiement. Prix en euros (TVA 0 %, HT = TTC). Le prix réellement payé est dans sales/payments.';
COMMENT ON COLUMN public.offers."slug" IS 'Identifiant texte (ex. al-baraka, liberty, al-baraka-200, slug de formation).';
COMMENT ON COLUMN public.offers."category" IS 'al_baraka = Pass AL BARAKA ; al_baraka_200 = même Pass vendu 2 400 € en 1 à 12×, à part pour bloquer les codes promo du Pass ; liberty = Pass Liberty ; a_la_carte = une formation.';
COMMENT ON COLUMN public.offers."label" IS 'Libellé affiché.';
COMMENT ON COLUMN public.offers."default_price_ht" IS 'Prix catalogue en euros (TVA 0 %).';
COMMENT ON COLUMN public.offers."min_installments_count" IS 'Nombre minimal d''échéances proposé.';
COMMENT ON COLUMN public.offers."max_installments_count" IS 'Nombre maximal d''échéances proposé.';
COMMENT ON COLUMN public.offers."status" IS 'active = en vente ; archived = retirée.';
COMMENT ON TABLE public.offres_coaching IS 'Une ligne = une offre de coaching individuel payant (actuellement une seule). Prix, coach, taux de commission coach et type d''évènement Calendly. Un paiement crée une vente custom_link via payment_links et une commission rôle coach. Prix en euros.';
COMMENT ON COLUMN public.offres_coaching."slug" IS 'Identifiant (ex. coaching-individuel), référencé par payment_links.offre_coaching.';
COMMENT ON COLUMN public.offres_coaching."prix" IS 'Prix en euros.';
COMMENT ON COLUMN public.offres_coaching."coach_id" IS 'Coach qui assure le coaching (profiles.id).';
COMMENT ON COLUMN public.offres_coaching."pourcentage_coach" IS 'Commission du coach en % du prix.';
COMMENT ON COLUMN public.offres_coaching."calendly_event_type" IS 'UUID du type d''évènement Calendly de réservation.';
COMMENT ON COLUMN public.offres_coaching."actif" IS 'false = offre fermée.';
COMMENT ON TABLE public.parcours IS 'ANCIENS parcours (structure phases → chapitres) : « al-baraka » et « liberty ». Tous deux masqués aux élèves (12/10 et 04/11/2026) ; leurs données restent. Les parcours actuels (Setting/Closing, CM, Liberty) sont dans formations.';
COMMENT ON COLUMN public.parcours."pass_type" IS 'Pass qui donne accès : al_baraka ou liberty.';
COMMENT ON COLUMN public.parcours."slug" IS 'al-baraka ou liberty.';
COMMENT ON COLUMN public.parcours."status" IS 'draft = brouillon ; published = en ligne ; archived = retiré.';
COMMENT ON COLUMN public.parcours."masque_eleves" IS 'Vrai = invisible pour les élèves (CEO seul) ; progression conservée.';
COMMENT ON TABLE public.parcours_chapitre_progress IS 'Une ligne = un chapitre de l''ANCIEN parcours (parcours_chapitres) terminé par un élève. Alimenté par l''élève, par l''auto-complétion quand la formation liée est terminée, et par recopie depuis les nouveaux parcours (déclencheurs de correspondance).';
COMMENT ON COLUMN public.parcours_chapitre_progress."chapitre_id" IS 'Chapitre de l''ancien parcours (parcours_chapitres.id).';
COMMENT ON COLUMN public.parcours_chapitre_progress."completed_at" IS 'Moment de la complétion (ou de la recopie).';
COMMENT ON TABLE public.parcours_chapitre_ressources IS 'Ressources (lien, PDF, image) d''un chapitre de l''ANCIEN parcours, éventuellement rattachées à une vidéo. Contenu éditorial.';
COMMENT ON COLUMN public.parcours_chapitre_ressources."type" IS 'pdf, image ou link.';
COMMENT ON COLUMN public.parcours_chapitre_ressources."video_id" IS 'Vidéo de rattachement (parcours_chapitre_videos.id). Null = ressource du chapitre.';
COMMENT ON TABLE public.parcours_chapitre_videos IS 'Vidéos (Vimeo) d''un chapitre de l''ANCIEN parcours. Contenu éditorial. Pas de suivi de visionnage par vidéo pour l''ancien parcours.';
COMMENT ON COLUMN public.parcours_chapitre_videos."duree_secondes" IS 'Durée en secondes.';
COMMENT ON COLUMN public.parcours_chapitre_videos."notes" IS 'Notes affichées sous la vidéo.';
COMMENT ON TABLE public.parcours_chapitres IS 'Chapitres de l''ANCIEN parcours, rangés par phase. Trois types : vidéo, renvoi vers une formation du catalogue, ou jalon (message d''étape).';
COMMENT ON COLUMN public.parcours_chapitres."phase_id" IS 'Phase (parcours_phases.id).';
COMMENT ON COLUMN public.parcours_chapitres."type" IS 'video = chapitre vidéo ; redirect_formation = ouvre une formation (formation_id), terminé quand elle l''est ; milestone = message de jalon.';
COMMENT ON COLUMN public.parcours_chapitres."formation_id" IS 'Formation débloquée par un chapitre redirect_formation.';
COMMENT ON COLUMN public.parcours_chapitres."milestone_message" IS 'Texte du jalon (type milestone).';
COMMENT ON COLUMN public.parcours_chapitres."theorie_chapitre_id" IS 'Chapitre de formation à valider avant d''ouvrir ce chapitre. Null = aucun prérequis.';
COMMENT ON COLUMN public.parcours_chapitres."status" IS 'draft, published ou archived.';
COMMENT ON TABLE public.parcours_correspondances_chapitres IS 'Table technique : relie un chapitre copié dans un nouveau parcours (copie_id) à son chapitre d''origine, soit dans une formation, soit dans l''ancien parcours. Sert aux déclencheurs qui cochent la progression des deux côtés. Explique les doublons de progression entre formations.';
COMMENT ON COLUMN public.parcours_correspondances_chapitres."copie_id" IS 'Chapitre copié (formation_chapitres.id, dans un parcours).';
COMMENT ON COLUMN public.parcours_correspondances_chapitres."source_chapitre_id" IS 'Chapitre d''origine dans une formation. Exclusif avec source_parcours_chapitre_id.';
COMMENT ON COLUMN public.parcours_correspondances_chapitres."source_parcours_chapitre_id" IS 'Chapitre d''origine dans l''ancien parcours (parcours_chapitres.id).';
COMMENT ON TABLE public.parcours_correspondances_quiz IS 'Table technique : relie un quiz copié dans un parcours à son quiz d''origine. Un quiz validé d''un côté crée une tentative validée de l''autre (déclencheur sur quiz_attempts).';
COMMENT ON COLUMN public.parcours_correspondances_quiz."copie_quiz_id" IS 'Quiz copié (quizzes.id).';
COMMENT ON COLUMN public.parcours_correspondances_quiz."source_quiz_id" IS 'Quiz d''origine (quizzes.id).';
COMMENT ON TABLE public.parcours_enrollments IS 'Inscription d''un élève à un ANCIEN parcours (al-baraka ou liberty), créée automatiquement à l''attribution d''un pass (déclencheur sur user_passes). Plus lue par l''application.';
COMMENT ON COLUMN public.parcours_enrollments."parcours_id" IS 'Parcours (parcours.id).';
COMMENT ON COLUMN public.parcours_enrollments."completed_at" IS 'Fin du parcours : aucun code qui le remplit trouvé, usage à confirmer.';
COMMENT ON TABLE public.parcours_parties_terminees IS 'Une ligne = une partie d''un nouveau parcours terminée par un élève (module de parcours-setter-closer ou parcours-community-management), notée une seule fois. Déclenche les déblocages (page activité, liens de paiement, rôles Discord, quiz d''organisation, formation Administratif).';
COMMENT ON COLUMN public.parcours_parties_terminees."module_id" IS 'Partie terminée (formation_modules.id).';
COMMENT ON COLUMN public.parcours_parties_terminees."termine_le" IS 'Date à laquelle la partie a été constatée terminée.';
COMMENT ON TABLE public.parcours_phases IS 'Phases de l''ANCIEN parcours (al-baraka, liberty), qui regroupent les chapitres. Contenu éditorial.';
COMMENT ON COLUMN public.parcours_phases."parcours_id" IS 'Parcours (parcours.id).';
COMMENT ON COLUMN public.parcours_phases."numero" IS 'Numéro de la phase dans le parcours.';
COMMENT ON TABLE public.payment_audit_log IS 'Journal des modifications d''échéances faites par le CEO depuis la page Paiements (RPC update/add/delete_payment_admin, recalculate_remaining_payments). Une ligne par action, avec l''état avant/après en JSON. Ne trace pas les changements faits par les webhooks ni les corrections SQL.';
COMMENT ON COLUMN public.payment_audit_log."payment_id" IS 'Échéance modifiée (payments.id) ; NULL pour un recalcul global.';
COMMENT ON COLUMN public.payment_audit_log."sale_id" IS 'Vente (sales.id).';
COMMENT ON COLUMN public.payment_audit_log."actor_id" IS 'Auteur (profiles.id).';
COMMENT ON COLUMN public.payment_audit_log."action" IS 'update = échéance modifiée ; create = échéance ajoutée ; delete = échéance supprimée ; recalculate = reste à payer réparti en nouvelles échéances.';
COMMENT ON COLUMN public.payment_audit_log."old_values" IS 'Ligne avant modification (JSON).';
COMMENT ON COLUMN public.payment_audit_log."new_values" IS 'Ligne après modification (JSON).';
COMMENT ON TABLE public.payment_links IS 'Une ligne = un lien de paiement /pay/ALB-PL-… : commande libre créée par le CEO, ou lien jetable auto-généré (Pass en différé, formation à la carte, Al Baraka 200, coaching individuel). Au paiement, stripe-webhook crée la vente (sale_type custom_link) et remplit sale_id. Montants en euros (TVA 0 %).';
COMMENT ON COLUMN public.payment_links."token" IS 'Jeton public ALB-PL-… du lien (masquée pour le connecteur).';
COMMENT ON COLUMN public.payment_links."product_label" IS 'Libellé du produit, repris dans sales.product.';
COMMENT ON COLUMN public.payment_links."total_amount" IS 'Total à payer en euros.';
COMMENT ON COLUMN public.payment_links."installments_count" IS 'Nombre d''échéances (1 à 24).';
COMMENT ON COLUMN public.payment_links."deposit_amount" IS 'Premier versement en euros, inférieur au total ; NULL = échéances égales (usage exact à confirmer).';
COMMENT ON COLUMN public.payment_links."deferred_start_date" IS 'Date du premier prélèvement différé ; NULL = paiement immédiat.';
COMMENT ON COLUMN public.payment_links."prefilled_contact_id" IS 'Contact pré-rempli (contacts.id).';
COMMENT ON COLUMN public.payment_links."status" IS 'active = en attente de paiement ; paid = payé (vente créée) ; cancelled = annulé par le CEO.';
COMMENT ON COLUMN public.payment_links."sale_id" IS 'Vente créée au paiement (sales.id).';
COMMENT ON COLUMN public.payment_links."paid_at" IS 'Date-heure du paiement.';
COMMENT ON COLUMN public.payment_links."auto_generated" IS 'true = lien jetable créé automatiquement par un parcours (pas par le CEO).';
COMMENT ON COLUMN public.payment_links."offre_coaching" IS 'Offre de coaching individuel (offres_coaching.slug) ; déclenche la commission coach.';
COMMENT ON COLUMN public.payment_links."reservation_creee_le" IS 'Création du lien de réservation Calendly du coaching.';
COMMENT ON TABLE public.payments IS 'Une ligne = une échéance (mensualité) d''une vente, payée ou à venir. Créée avec la vente (webhook Stripe/systeme.io, saisie) et modifiée par le CEO (page Paiements, journalisée dans payment_audit_log). Montants en euros TTC (= HT, TVA 0 %). Source de vérité de l''encaissé : status=''paid'' et paid_at. Une ligne Studio par facture Stripe payée.';
COMMENT ON COLUMN public.payments."sale_id" IS 'Vente (sales.id).';
COMMENT ON COLUMN public.payments."contact_id" IS 'Client (contacts.id), rempli automatiquement depuis la vente.';
COMMENT ON COLUMN public.payments."payment_number" IS 'Rang de l''échéance dans la vente (1 = première).';
COMMENT ON COLUMN public.payments."total_payments" IS 'Nombre total d''échéances de la vente au moment présent.';
COMMENT ON COLUMN public.payments."amount" IS 'Montant de l''échéance en euros (TVA 0 %). La dernière échéance absorbe les centimes d''arrondi.';
COMMENT ON COLUMN public.payments."due_date" IS 'Date d''échéance prévue.';
COMMENT ON COLUMN public.payments."paid_at" IS 'Date d''encaissement (date, sans heure). Toujours remplie si status=''paid''. Utiliser ce champ pour l''encaissé d''une période.';
COMMENT ON COLUMN public.payments."status" IS 'pending = à venir (en retard si due_date < aujourd''hui) ; paid = encaissée ; lost = perdue (impayé définitif, les suivantes passent aussi en lost) ; late = prévu mais inutilisé.';
COMMENT ON COLUMN public.payments."payment_method" IS 'Moyen : stripe/STRIPE = Stripe (casse incohérente) ; carte, virement, especes, cheque = saisi à la main ; manual = ancienne saisie ; NULL = non renseigné.';
COMMENT ON COLUMN public.payments."notes" IS 'Commentaire libre de l''équipe.';
COMMENT ON COLUMN public.payments."stripe_payment_intent_id" IS 'PaymentIntent Stripe ayant réglé l''échéance (unique quand non NULL).';
COMMENT ON COLUMN public.payments."stripe_invoice_id" IS 'Facture Stripe ayant réglé l''échéance (unique quand non NULL).';
COMMENT ON COLUMN public.payments."stripe_subscription_id" IS 'Abonnement/échéancier Stripe qui prélève cette vente ; NULL si paiement manuel ou systeme.io.';
COMMENT ON TABLE public.pending_scoring_tokens IS 'Jetons qui rattachent un questionnaire de scoring à la personne inscrite. Créés par tunnel-lead-submit (déjà consommés, rattachement direct) et autrefois par le webhook Systeme.io (rapprochement par IP via match-scoring-token). Table technique.';
COMMENT ON COLUMN public.pending_scoring_tokens."funnel_slug" IS 'Questionnaire (quiz_funnel_configs.slug).';
COMMENT ON COLUMN public.pending_scoring_tokens."contact_email" IS 'E-mail de l''inscrit. Donnée personnelle.';
COMMENT ON COLUMN public.pending_scoring_tokens."contact_first_name" IS 'Prénom. Donnée personnelle.';
COMMENT ON COLUMN public.pending_scoring_tokens."contact_last_name" IS 'Nom. Donnée personnelle.';
COMMENT ON COLUMN public.pending_scoring_tokens."contact_phone" IS 'Téléphone. Donnée personnelle.';
COMMENT ON COLUMN public.pending_scoring_tokens."systemio_contact_id" IS 'Identifiant Systeme.io (ancien flux).';
COMMENT ON COLUMN public.pending_scoring_tokens."client_ip" IS 'IP de l''inscrit (rapprochement de l''ancien flux).';
COMMENT ON COLUMN public.pending_scoring_tokens."consumed" IS 'Vrai = jeton déjà utilisé.';
COMMENT ON COLUMN public.pending_scoring_tokens."consumed_at" IS 'Date d''utilisation.';
COMMENT ON COLUMN public.pending_scoring_tokens."expires_at" IS 'Expiration du jeton.';
COMMENT ON COLUMN public.pending_scoring_tokens."raw_webhook_payload" IS 'Payload brut reçu de Systeme.io, pour débogage.';
COMMENT ON TABLE public.personal_brand_weeks IS 'Une ligne = une semaine générée par l''IA dans un cycle Personal Brand de 4 semaines (thème, scripts, stories) pour un élève. Unique (user_id, cycle_id, week_num). La semaine suivante s''ouvre quand la précédente est publiée.';
COMMENT ON COLUMN public.personal_brand_weeks."mode" IS 'pass = espace Personal Brand AL BARAKA ; liberty = espace Liberty (propre offre).';
COMMENT ON COLUMN public.personal_brand_weeks."cycle_id" IS 'Identifiant du cycle de 4 semaines (glissant, pas un mois calendaire).';
COMMENT ON COLUMN public.personal_brand_weeks."week_num" IS 'Semaine du cycle, 1 à 4 (Notoriété → Crédibilité → Engagement → Conversion).';
COMMENT ON COLUMN public.personal_brand_weeks."scripts" IS 'Scripts vidéo générés (JSON).';
COMMENT ON COLUMN public.personal_brand_weeks."stories" IS 'Stories générées (JSON).';
COMMENT ON COLUMN public.personal_brand_weeks."published_at" IS 'L''élève a marqué la semaine comme publiée. Null = pas encore.';
COMMENT ON TABLE public.preuves_consentement IS 'Preuve de l''acceptation des CGV et de la renonciation au droit de rétractation lors d''une commande : une ligne par intention de paiement Stripe, écrite par create-payment-intent avant la vente. Lue par stripe-webhook pour le contrat. Ne jamais purger. sale_id, produit, montant_total et mensualites ne sont pas remplis par le code actuel (souvent NULL).';
COMMENT ON COLUMN public.preuves_consentement."stripe_intent_id" IS 'Identifiant Stripe de l''intention de paiement (PaymentIntent ou SetupIntent), unique.';
COMMENT ON COLUMN public.preuves_consentement."sale_id" IS 'Vente liée (sales.id). Non rempli par le code actuel : relier plutôt par e-mail et date.';
COMMENT ON COLUMN public.preuves_consentement."email" IS 'E-mail de l''acheteur. Donnée personnelle.';
COMMENT ON COLUMN public.preuves_consentement."nom_complet" IS 'Nom de l''acheteur. Donnée personnelle.';
COMMENT ON COLUMN public.preuves_consentement."produit" IS 'Produit commandé. Usage à confirmer (non transmis par le code actuel).';
COMMENT ON COLUMN public.preuves_consentement."montant_total" IS 'Montant total de la commande. Unité à confirmer (non transmis par le code actuel).';
COMMENT ON COLUMN public.preuves_consentement."mensualites" IS 'Nombre de mensualités. Usage à confirmer (non transmis par le code actuel).';
COMMENT ON COLUMN public.preuves_consentement."version_cgv" IS 'Version des CGV acceptée.';
COMMENT ON COLUMN public.preuves_consentement."engagements" IS 'Cases cochées avec leur texte exact au moment de la commande (JSON).';
COMMENT ON COLUMN public.preuves_consentement."adresse_ip" IS 'Adresse IP de l''acheteur (preuve). Donnée personnelle.';
COMMENT ON COLUMN public.preuves_consentement."navigateur" IS 'User-agent du navigateur (preuve).';
COMMENT ON COLUMN public.preuves_consentement."cree_le" IS 'Date de la preuve (création de l''intention de paiement).';
COMMENT ON TABLE public.profiles IS 'Une ligne par compte de la plateforme (même id que auth.users) : équipe interne et élèves. Rôles : ceo ; collaborateur (setter/closer, niveau confirme ou intermediaire) ; apporteur (élèves et apporteurs d''affaires) ; agence. Contient des données personnelles et bancaires (RIB) : ne jamais les exposer. Les droits d''accès des élèves se lisent dans user_passes et formation_enrollments.';
COMMENT ON COLUMN public.profiles."email" IS 'E-mail de connexion (donnée personnelle).';
COMMENT ON COLUMN public.profiles."full_name" IS 'Nom complet (donnée personnelle).';
COMMENT ON COLUMN public.profiles."phone" IS 'Téléphone (donnée personnelle).';
COMMENT ON COLUMN public.profiles."role" IS 'ceo = direction ; collaborateur = équipe commerciale (setter/closer) ; apporteur = élève ou apporteur d''affaires ; agence = agence marketing (accès limité).';
COMMENT ON COLUMN public.profiles."is_also_apporteur" IS 'true = peut aussi toucher des commissions d''apporteur ; obligatoire pour un collaborateur.';
COMMENT ON COLUMN public.profiles."can_add_instagram_leads" IS 'true = peut créer des leads Instagram à la main.';
COMMENT ON COLUMN public.profiles."timezone" IS 'Fuseau de la personne (Europe/Paris, Africa/Casablanca, Asia/Dubai).';
COMMENT ON COLUMN public.profiles."siret" IS 'SIRET pour la facturation des commissions.';
COMMENT ON COLUMN public.profiles."bank_country" IS 'Pays de la banque.';
COMMENT ON COLUMN public.profiles."bank_details" IS 'Coordonnées bancaires extraites du RIB (IBAN, BIC…) des membres de l''équipe et apporteurs, pour le paiement des commissions. Donnée sensible.';
COMMENT ON COLUMN public.profiles."bank_rib_url" IS 'Chemin du fichier RIB dans le stockage. Donnée sensible.';
COMMENT ON COLUMN public.profiles."onboarding_completed" IS 'true = parcours d''accueil terminé.';
COMMENT ON COLUMN public.profiles."fixed_salary" IS 'Obsolète : salaire fixe historique ; la référence est la table salary_periods.';
COMMENT ON COLUMN public.profiles."fixed_salary_active" IS 'Obsolète : remplacé par salary_periods.';
COMMENT ON COLUMN public.profiles."collaborateur_level" IS 'Niveau d''un collaborateur : confirme ou intermediaire (statuts de lead autorisés différents).';
COMMENT ON COLUMN public.profiles."is_active" IS 'false = compte désactivé.';
