COMMENT ON COLUMN public.recon_stripe_customers."customer_id" IS 'Identifiant client Stripe (cus_…).';
COMMENT ON COLUMN public.recon_stripe_customers."email" IS 'E-mail Stripe (donnée personnelle).';
COMMENT ON COLUMN public.recon_stripe_customers."name" IS 'Nom Stripe (donnée personnelle).';
COMMENT ON COLUMN public.recon_stripe_customers."delinquent" IS 'true = Stripe signale un impayé en cours à la date de l''instantané.';
COMMENT ON COLUMN public.recon_stripe_customers."raw" IS 'Objet Stripe brut (JSON).';
